select public.upsert_bank_question($json${"id":"hist2-easy-001","type":"choice","level":"easy","testament":"ot","book":"JOS","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo Josué 1:1, depois da morte de Moisés, a quem falou o SENHOR?","bible_ref":"Josué 1:1","verse_text":"E aconteceu depois da morte de Moisés servo do SENHOR, que o SENHOR falou a Josué filho de Num, assistente de Moisés, dizendo:"},"fr":{"prompt":"Selon Josué 1:1, après la mort de Moïse, à qui l’Éternel parla-t-il ?","bible_ref":"Josué 1:1","verse_text":"Après la mort de Moïse, serviteur de l’Éternel, l’Éternel dit à Josué, fils de Nun, serviteur de Moïse:"},"en":{"prompt":"According to Joshua 1:1, after the death of Moses, to whom did the LORD speak?","bible_ref":"Joshua 1:1","verse_text":"Now after the death of Moses the servant of the LORD it came to pass, that the LORD spake unto Joshua the son of Nun, Moses’ minister, saying,"},"es":{"prompt":"Según Josué 1:1, después de la muerte de Moisés, ¿a quién habló Jehová?","bible_ref":"Josué 1:1","verse_text":"Y aconteció después de la muerte de Moisés siervo de Jehová, que Jehová habló á Josué hijo de Nun, ministro de Moisés, diciendo:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Josué"},"fr":{"text":"Josué"},"en":{"text":"Joshua"},"es":{"text":"Josué"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Arão"},"fr":{"text":"Aaron"},"en":{"text":"Aaron"},"es":{"text":"Aarón"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Calebe"},"fr":{"text":"Caleb"},"en":{"text":"Caleb"},"es":{"text":"Caleb"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-002","type":"choice","level":"easy","testament":"ot","book":"JOS","chapter":6,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"O que levavam os sete sacerdotes diante da arca, à volta de Jericó?","bible_ref":"Josué 6:4","verse_text":"E sete sacerdotes levarão sete trombetas de chifres de carneiros diante da arca; e ao sétimo dia dareis sete voltas à cidade, e os sacerdotes tocarão as trombetas."},"fr":{"prompt":"Que portaient les sept sacrificateurs devant l’arche, autour de Jéricho ?","bible_ref":"Josué 6:4","verse_text":"Sept sacrificateurs porteront devant l’arche sept trompettes retentissantes; le septième jour, vous ferez sept fois le tour de la ville; et les sacrificateurs sonneront des trompettes."},"en":{"prompt":"What did the seven priests carry before the ark around Jericho?","bible_ref":"Joshua 6:4","verse_text":"And seven priests shall bear before the ark seven trumpets of rams’ horns: and the seventh day ye shall compass the city seven times, and the priests shall blow with the trumpets."},"es":{"prompt":"¿Qué llevaban los siete sacerdotes delante del arca, alrededor de Jericó?","bible_ref":"Josué 6:4","verse_text":"Y siete sacerdotes llevarán siete bocinas de cuernos de carneros delante del arca; y al séptimo día daréis siete vueltas á la ciudad, y los sacerdotes tocarán las bocinas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Sete trombetas"},"fr":{"text":"Sept trompettes"},"en":{"text":"Seven trumpets"},"es":{"text":"Siete bocinas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Sete espadas"},"fr":{"text":"Sept épées"},"en":{"text":"Seven swords"},"es":{"text":"Siete espadas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sete lâmpadas"},"fr":{"text":"Sept lampes"},"en":{"text":"Seven lamps"},"es":{"text":"Siete lámparas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-003","type":"choice","level":"easy","testament":"ot","book":"JOS","chapter":6,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"No sétimo dia, quantas voltas deu o povo à cidade de Jericó?","bible_ref":"Josué 6:15","verse_text":"E ao sétimo dia levantaram-se quando subia a alva, e deram volta à cidade da mesma maneira sete vezes: somente este dia deram volta ao redor dela sete vezes."},"fr":{"prompt":"Le septième jour, combien de fois le peuple fit-il le tour de Jéricho ?","bible_ref":"Josué 6:15","verse_text":"Le septième jour, ils se levèrent de bon matin, dès l’aurore, et ils firent de la même manière sept fois le tour de la ville; ce fut le seul jour où ils firent sept fois le tour de la ville."},"en":{"prompt":"On the seventh day, how many times did the people go around Jericho?","bible_ref":"Joshua 6:15","verse_text":"And it came to pass on the seventh day, that they rose early about the dawning of the day, and compassed the city after the same manner seven times: only on that day they compassed the city seven times."},"es":{"prompt":"El séptimo día, ¿cuántas vueltas dio el pueblo a Jericó?","bible_ref":"Josué 6:15","verse_text":"Y al séptimo día levantáronse cuando subía el alba, y dieron vuelta á la ciudad de la misma manera siete veces: solamente este día dieron vuelta alrededor de ella siete veces."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Sete"},"fr":{"text":"Sept"},"en":{"text":"Seven"},"es":{"text":"Siete"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Três"},"fr":{"text":"Trois"},"en":{"text":"Three"},"es":{"text":"Tres"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Doze"},"fr":{"text":"Douze"},"en":{"text":"Twelve"},"es":{"text":"Doce"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-004","type":"choice","level":"easy","testament":"ot","book":"JOS","chapter":2,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"Como ajudou Raabe os dois espias a fugir de Jericó?","bible_ref":"Josué 2:15","verse_text":"Então ela os fez descer com uma corda pela janela; porque sua casa estava à parede do muro, e ela vivia no muro."},"fr":{"prompt":"Comment Rahab aida-t-elle les deux espions à s’enfuir de Jéricho ?","bible_ref":"Josué 2:15","verse_text":"Elle les fit descendre avec une corde par la fenêtre, car la maison qu’elle habitait était sur la muraille de la ville."},"en":{"prompt":"How did Rahab help the two spies escape from Jericho?","bible_ref":"Joshua 2:15","verse_text":"Then she let them down by a cord through the window: for her house was upon the town wall, and she dwelt upon the wall."},"es":{"prompt":"¿Cómo ayudó Rahab a los dos espías a huir de Jericó?","bible_ref":"Josué 2:15","verse_text":"Entonces ella los hizo descender con una cuerda por la ventana; porque su casa estaba á la pared del muro, y ella vivía en el muro."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Fê-los descer por uma corda pela janela"},"fr":{"text":"Elle les fit descendre avec une corde par la fenêtre"},"en":{"text":"She let them down by a cord through the window"},"es":{"text":"Los hizo descender con una cuerda por la ventana"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Escondeu-os num barco no rio"},"fr":{"text":"Elle les cacha dans une barque sur le fleuve"},"en":{"text":"She hid them in a boat on the river"},"es":{"text":"Los escondió en una barca en el río"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Abriu-lhes a porta da cidade"},"fr":{"text":"Elle leur ouvrit la porte de la ville"},"en":{"text":"She opened the city gate for them"},"es":{"text":"Les abrió la puerta de la ciudad"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-005","type":"order","level":"easy","testament":"ot","book":"JOS","chapter":2,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"Josué 2:1","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"Josué 2:1","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"Joshua 2:1","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"Josué 2:1","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Josué envia dois espias a Jericó","ref":"Josué 2:1"},"fr":{"text":"Josué envoie deux espions à Jéricho","ref":"Josué 2:1"},"en":{"text":"Joshua sends two spies to Jericho","ref":"Joshua 2:1"},"es":{"text":"Josué envía dos espías a Jericó","ref":"Josué 2:1"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O povo atravessa o Jordão em seco","ref":"Josué 3:17"},"fr":{"text":"Le peuple traverse le Jourdain à sec","ref":"Josué 3:17"},"en":{"text":"The people cross the Jordan on dry ground","ref":"Joshua 3:17"},"es":{"text":"El pueblo pasa el Jordán en seco","ref":"Josué 3:17"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Josué ergue doze pedras em Gilgal","ref":"Josué 4:20"},"fr":{"text":"Josué dresse douze pierres à Guilgal","ref":"Josué 4:20"},"en":{"text":"Joshua sets up twelve stones in Gilgal","ref":"Joshua 4:20"},"es":{"text":"Josué erige doce piedras en Gilgal","ref":"Josué 4:20"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O muro de Jericó cai","ref":"Josué 6:20"},"fr":{"text":"La muraille de Jéricho tombe","ref":"Josué 6:20"},"en":{"text":"The wall of Jericho falls down","ref":"Joshua 6:20"},"es":{"text":"Cae el muro de Jericó","ref":"Josué 6:20"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-006","type":"verse","level":"easy","testament":"ot","book":"JOS","chapter":1,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Ninguém poderá resistir a ti em todos os dias de tua vida: como eu fui com _____, serei contigo; não te deixarei, nem te desampararei.","bible_ref":"Josué 1:5","verse_text":"Ninguém poderá resistir a ti em todos os dias de tua vida: como eu fui com Moisés, serei contigo; não te deixarei, nem te desampararei."},"fr":{"prompt":"Nul ne tiendra devant toi, tant que tu vivras. Je serai avec toi, comme j’ai été avec _____; je ne te délaisserai point, je ne t’abandonnerai point.","bible_ref":"Josué 1:5","verse_text":"Nul ne tiendra devant toi, tant que tu vivras. Je serai avec toi, comme j’ai été avec Moïse; je ne te délaisserai point, je ne t’abandonnerai point."},"en":{"prompt":"There shall not any man be able to stand before thee all the days of thy life: as I was with _____, so I will be with thee: I will not fail thee, nor forsake thee.","bible_ref":"Joshua 1:5","verse_text":"There shall not any man be able to stand before thee all the days of thy life: as I was with Moses, so I will be with thee: I will not fail thee, nor forsake thee."},"es":{"prompt":"Nadie te podrá hacer frente en todos los días de tu vida: como yo fuí con _____, seré contigo; no te dejaré, ni te desampararé.","bible_ref":"Josué 1:5","verse_text":"Nadie te podrá hacer frente en todos los días de tu vida: como yo fuí con Moisés, seré contigo; no te dejaré, ni te desampararé."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Noé"},"fr":{"text":"Noé"},"en":{"text":"Noah"},"es":{"text":"Noé"}}},{"position":2,"is_correct":true,"texts":{"pt":{"text":"Moisés"},"fr":{"text":"Moïse"},"en":{"text":"Moses"},"es":{"text":"Moisés"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Arão"},"fr":{"text":"Aaron"},"en":{"text":"Aaron"},"es":{"text":"Aarón"}}},{"position":4,"is_correct":false,"texts":