select public.upsert_bank_question($json${"id":"hist2-easy-007","type":"choice","level":"easy","testament":"ot","book":"JDG","chapter":14,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Que animal veio a rugir contra Sansão nas vinhas de Timna?","bible_ref":"Juízes 14:5","verse_text":"E Sansão desceu com seu pai e com sua mãe a Timna: e quando chegaram às vinhas de Timna, eis que um leão jovem vinha bramando até ele."},"fr":{"prompt":"Quel animal vint en rugissant à la rencontre de Samson dans les vignes de Thimna ?","bible_ref":"Juges 14:5","verse_text":"Samson descendit avec son père et sa mère à Thimna. Lorsqu’ils arrivèrent aux vignes de Thimna, voici, un jeune lion rugissant vint à sa rencontre."},"en":{"prompt":"What animal roared against Samson in the vineyards of Timnath?","bible_ref":"Judges 14:5","verse_text":"Then went Samson down, and his father and his mother, to Timnath, and came to the vineyards of Timnath: and, behold, a young lion roared against him."},"es":{"prompt":"¿Qué animal vino bramando hacia Samsón en las viñas de Timnah?","bible_ref":"Jueces 14:5","verse_text":"Y Samsón descendió con su padre y con su madre á Timnah: y como llegaron á las viñas de Timnah, he aquí un cachorro de león que venía bramando hacia él."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um leão"},"fr":{"text":"Un lion"},"en":{"text":"A lion"},"es":{"text":"Un león"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um urso"},"fr":{"text":"Un ours"},"en":{"text":"A bear"},"es":{"text":"Un oso"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um lobo"},"fr":{"text":"Un loup"},"en":{"text":"A wolf"},"es":{"text":"Un lobo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-008","type":"choice","level":"easy","testament":"ot","book":"JDG","chapter":15,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"Com que feriu Sansão mil homens?","bible_ref":"Juízes 15:15","verse_text":"E achando uma queixada de asno fresca, estendeu a mão e tomou-a, e feriu com ela a mil homens."},"fr":{"prompt":"Avec quoi Samson tua-t-il mille hommes ?","bible_ref":"Juges 15:15","verse_text":"Il trouva une mâchoire d’âne fraîche, il étendit sa main pour la prendre, et il en tua mille hommes."},"en":{"prompt":"With what did Samson slay a thousand men?","bible_ref":"Judges 15:15","verse_text":"And he found a new jawbone of an ass, and put forth his hand, and took it, and slew a thousand men therewith."},"es":{"prompt":"¿Con qué hirió Samsón a mil hombres?","bible_ref":"Jueces 15:15","verse_text":"Y hallando una quijada de asno fresca, extendió la mano y tomóla, é hirió con ella á mil hombres."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Com uma queixada de asno"},"fr":{"text":"Avec une mâchoire d’âne"},"en":{"text":"With a jawbone of an ass"},"es":{"text":"Con una quijada de asno"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Com uma espada"},"fr":{"text":"Avec une épée"},"en":{"text":"With a sword"},"es":{"text":"Con una espada"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Com uma lança"},"fr":{"text":"Avec une lance"},"en":{"text":"With a spear"},"es":{"text":"Con una lanza"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-009","type":"choice","level":"easy","testament":"ot","book":"JDG","chapter":16,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Como se chamava a mulher que Sansão amou no vale de Soreque?","bible_ref":"Juízes 16:4","verse_text":"Depois disto aconteceu que se apaixonou por uma mulher no vale de Soreque, a qual se chamava Dalila."},"fr":{"prompt":"Comment s’appelait la femme que Samson aima dans la vallée de Sorek ?","bible_ref":"Juges 16:4","verse_text":"Après cela, il aima une femme dans la vallée de Sorek. Elle se nommait Delila."},"en":{"prompt":"What was the name of the woman Samson loved in the valley of Sorek?","bible_ref":"Judges 16:4","verse_text":"And it came to pass afterward, that he loved a woman in the valley of Sorek, whose name was Delilah."},"es":{"prompt":"¿Cómo se llamaba la mujer que Samsón amó en el valle de Sorec?","bible_ref":"Jueces 16:4","verse_text":"Después de esto aconteció que se enamoró de una mujer en el valle de Sorec, la cual se llamaba Dalila."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Dalila"},"fr":{"text":"Delila"},"en":{"text":"Delilah"},"es":{"text":"Dalila"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Rute"},"fr":{"text":"Ruth"},"en":{"text":"Ruth"},"es":{"text":"Ruth"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Débora"},"fr":{"text":"Débora"},"en":{"text":"Deborah"},"es":{"text":"Débora"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-010","type":"choice","level":"easy","testament":"ot","book":"JDG","chapter":7,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"O que deu Gideão a cada um dos seus trezentos homens?","bible_ref":"Juízes 7:16","verse_text":"E repartindo os trezentos homens em três esquadrões, deu a cada um deles trombetas em suas mãos, e cântaros vazios com tochas ardendo dentro dos cântaros."},"fr":{"prompt":"Que donna Gédéon à chacun de ses trois cents hommes ?","bible_ref":"Juges 7:16","verse_text":"Il divisa en trois corps les trois cents hommes, et il leur remit à tous des trompettes et des cruches vides, avec des flambeaux dans les cruches."},"en":{"prompt":"What did Gideon give to each of his three hundred men?","bible_ref":"Judges 7:16","verse_text":"And he divided the three hundred men into three companies, and he put a trumpet in every man’s hand, with empty pitchers, and lamps within the pitchers."},"es":{"prompt":"¿Qué dio Gedeón a cada uno de sus trescientos hombres?","bible_ref":"Jueces 7:16","verse_text":"Y repartiendo los trescientos hombres en tres escuadrones, dió á cada uno de ellos bocinas en sus manos, y cántaros vacíos con teas ardiendo dentro de los cántaros."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma trombeta e um cântaro com uma tocha"},"fr":{"text":"Une trompette et une cruche avec un flambeau"},"en":{"text":"A trumpet and a pitcher with a lamp"},"es":{"text":"Una bocina y un cántaro con una tea"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma espada e um escudo"},"fr":{"text":"Une épée et un bouclier"},"en":{"text":"A sword and a shield"},"es":{"text":"Una espada y un escudo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um arco e flechas"},"fr":{"text":"Un arc et des flèches"},"en":{"text":"A bow and arrows"},"es":{"text":"Un arco y saetas"}}}]}$json$::jsonb);
