select public.upsert_bank_question($json${"id":"hist2-easy-012","type":"verse","level":"easy","testament":"ot","book":"JDG","chapter":2,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Mas o SENHOR suscitou _____ que os livrassem da mão dos que os despojavam.","bible_ref":"Juízes 2:16","verse_text":"Mas o SENHOR suscitou juízes que os livrassem da mão dos que os despojavam."},"fr":{"prompt":"L’Éternel suscita des _____, afin qu’ils les délivrassent de la main de ceux qui les pillaient.","bible_ref":"Juges 2:16","verse_text":"L’Éternel suscita des juges, afin qu’ils les délivrassent de la main de ceux qui les pillaient."},"en":{"prompt":"Nevertheless the LORD raised up _____, which delivered them out of the hand of those that spoiled them.","bible_ref":"Judges 2:16","verse_text":"Nevertheless the LORD raised up judges, which delivered them out of the hand of those that spoiled them."},"es":{"prompt":"Mas Jehová suscitó _____ que los librasen de mano de los que los despojaban.","bible_ref":"Jueces 2:16","verse_text":"Mas Jehová suscitó jueces que los librasen de mano de los que los despojaban."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"juízes"},"fr":{"text":"juges"},"en":{"text":"judges"},"es":{"text":"jueces"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"anjos"},"fr":{"text":"anges"},"en":{"text":"angels"},"es":{"text":"ángeles"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"reis"},"fr":{"text":"rois"},"en":{"text":"kings"},"es":{"text":"reyes"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"profetas"},"fr":{"text":"prophètes"},"en":{"text":"prophets"},"es":{"text":"profetas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-013","type":"choice","level":"easy","testament":"ot","book":"RUT","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Porque foi um homem de Belém de Judá viver nos campos de Moabe com a família?","bible_ref":"Rute 1:1","verse_text":"E aconteceu nos dias que governavam os juízes, que houve fome na terra. E um homem de Belém de Judá, foi a peregrinar nos campos de Moabe, ele e sua mulher, e dois filhos seus."},"fr":{"prompt":"Pourquoi un homme de Bethléhem de Juda partit-il séjourner au pays de Moab avec sa famille ?","bible_ref":"Ruth 1:1","verse_text":"Du temps des juges, il y eut une famine dans le pays. Un homme de Bethléhem de Juda partit, avec sa femme et ses deux fils, pour faire un séjour dans le pays de Moab."},"en":{"prompt":"Why did a man of Beth-lehem-judah go to sojourn in the country of Moab with his family?","bible_ref":"Ruth 1:1","verse_text":"Now it came to pass in the days when the judges ruled, that there was a famine in the land. And a certain man of Beth-lehem-judah went to sojourn in the country of Moab, he, and his wife, and his two sons."},"es":{"prompt":"¿Por qué un varón de Beth-lehem de Judá fue a vivir a los campos de Moab con su familia?","bible_ref":"Rut 1:1","verse_text":"Y aconteció en los días que gobernaban los jueces, que hubo hambre en la tierra. Y un varón de Beth-lehem de Judá, fué á peregrinar en los campos de Moab, él y su mujer, y dos hijos suyos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Porque havia fome na terra"},"fr":{"text":"Parce qu’il y avait une famine dans le pays"},"en":{"text":"Because there was a famine in the land"},"es":{"text":"Porque había hambre en la tierra"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Porque havia guerra"},"fr":{"text":"Parce qu’il y avait la guerre"},"en":{"text":"Because there was a war"},"es":{"text":"Porque había guerra"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Porque houve um grande dilúvio"},"fr":{"text":"Parce qu’il y eut une grande inondation"},"en":{"text":"Because there was a great flood"},"es":{"text":"Porque hubo una gran inundación"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-014","type":"choice","level":"easy","testament":"ot","book":"RUT","chapter":2,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Como se chamava o parente rico do marido de Noemi?","bible_ref":"Rute 2:1","verse_text":"E tinha Noemi um parente de seu marido, homem poderoso e rico, da família de Elimeleque, o qual se chamava Boaz."},"fr":{"prompt":"Comment s’appelait le riche parent du mari de Naomi ?","bible_ref":"Ruth 2:1","verse_text":"Naomi avait un parent de son mari. C’était un homme puissant et riche, de la famille d’Élimélec, et qui se nommait Boaz."},"en":{"prompt":"What was the name of the rich kinsman of Naomi’s husband?","bible_ref":"Ruth 2:1","verse_text":"And Naomi had a kinsman of her husband’s, a mighty man of wealth, of the family of Elimelech; and his name was Boaz."},"es":{"prompt":"¿Cómo se llamaba el pariente poderoso del marido de Noemi?","bible_ref":"Rut 2:1","verse_text":"Y tenía Noemi un pariente de su marido, varón poderoso y de hecho, de la familia de Elimelech, el cual se llamaba Booz."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Boaz"},"fr":{"text":"Boaz"},"en":{"text":"Boaz"},"es":{"text":"Booz"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Obede"},"fr":{"text":"Obed"},"en":{"text":"Obed"},"es":{"text":"Obed"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jessé"},"fr":{"text":"Isaï"},"en":{"text":"Jesse"},"es":{"text":"Isaí"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-015","type":"verse","level":"easy","testament":"ot","book":"RUT","chapter":2,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"O SENHOR recompense tua obra, e tua remuneração seja cheia pelo SENHOR Deus de Israel, que vieste para cobrir-te debaixo de suas _____.","bible_ref":"Rute 2:12","verse_text":"O SENHOR recompense tua obra, e tua remuneração seja cheia pelo SENHOR Deus de Israel, que vieste para cobrir-te debaixo de suas asas."},"fr":{"prompt":"Que l’Éternel te rende ce que tu as fait, et que ta récompense soit entière de la part de l’Éternel, le Dieu d’Israël, sous les _____ duquel tu es venue te réfugier!","bible_ref":"Ruth 2:12","verse_text":"Que l’Éternel te rende ce que tu as fait, et que ta récompense soit entière de la part de l’Éternel, le Dieu d’Israël, sous les ailes duquel tu es venue te réfugier!"},"en":{"prompt":"The LORD recompense thy work, and a full reward be given thee of the LORD God of Israel, under whose _____ thou art come to trust.","bible_ref":"Ruth 2:12","verse_text":"The LORD recompense thy work, and a full reward be given thee of the LORD God of Israel, under whose wings thou art come to trust."},"es":{"prompt":"Jehová galardone tu obra, y tu remuneración sea llena por Jehová Dios de Israel, que has venido para cubrirte debajo de sus _____.","bible_ref":"Rut 2:12","verse_text":"Jehová galardone tu obra, y tu remuneración sea llena por Jehová Dios de Israel, que has venido para cubrirte debajo de sus alas."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"tendas"},"fr":{"text":"tentes"},"en":{"text":"tents"},"es":{"text":"tiendas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"mãos"},"fr":{"text":"mains"},"en":{"text":"hands"},"es":{"text":"manos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"pernas"},"fr":{"text":"jambes"},"en":{"text":"legs"},"es":{"text":"piernas"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"asas"},"fr":{"text":"ailes"},"en":{"text":"wings"},"es":{"text":"alas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-016","type":"choice","level":"easy","testament":"ot","book":"1SA","chapter":3,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Quando ouviu chamar de noite, a quem correu o menino Samuel?","bible_ref":"1 Samuel 3:5","verse_text":"E correndo logo a Eli, disse: Eis-me aqui; para que me chamaste? E Eli lhe disse: Eu não chamei; volta-te a deitar. E ele se voltou, e deitou-se."},"fr":{"prompt":"Quand il entendit qu’on l’appelait la nuit, vers qui le jeune Samuel courut-il ?","bible_ref":"1 Samuel 3:5","verse_text":"Et il courut vers Éli, et dit: Me voici, car tu m’as appelé. Éli répondit: Je n’ai point appelé; retourne te coucher. Et il alla se coucher."},"en":{"prompt":"When he heard someone call in the night, to whom did young Samuel run?","bible_ref":"1 Samuel 3:5","verse_text":"And he ran unto Eli, and said, Here am I; for thou calledst me. And he said, I called not; lie down again. And he went and lay down."},"es":{"prompt":"Cuando oyó que lo llamaban de noche, ¿a quién corrió el niño Samuel?","bible_ref":"1 Samuel 3:5","verse_text":"Y corriendo luego á Eli, dijo: Heme aquí; ¿para qué me llamaste? Y Eli le dijo: Yo no he llamado; vuélvete á acostar. Y él se volvió, y acostóse."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A Eli"},"fr":{"text":"Vers Éli"},"en":{"text":"To Eli"},"es":{"text":"A Eli"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A Ana, a sua mãe"},"fr":{"text":"Vers Anne, sa mère"},"en":{"text":"To Hannah, his mother"},"es":{"text":"A Anna, su madre"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A Saul"},"fr":{"text":"Vers Saül"},"en":{"text":"To Saul"},"es":{"text":"A Saúl"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-017","type":"choice","level":"easy","testament":"ot","book":"1SA","chapter":17,"verse_start":40,"verse_end":40,"texts":{"pt":{"prompt":"Quantas pedras lisas escolheu David no ribeiro?","bible_ref":"1 Samuel 17:40","verse_text":"Tomou seu cajado em sua mão, e escolheu para si cinco pedras lisas do ribeiro, e as pôs no saco pastoril e na sacola que trazia, e com sua funda em sua mão foi até o filisteu."},"fr":{"prompt":"Combien de pierres polies David choisit-il dans le torrent ?","bible_ref":"1 Samuel 17:40","verse_text":"Il prit en main son bâton, choisit dans le torrent cinq pierres polies, et les mit dans sa gibecière de berger et dans sa poche. Puis, sa fronde à la main, il s’avança contre le Philistin."},"en":{"prompt":"How many smooth stones did David choose out of the brook?","bible_ref":"1 Samuel 17:40","verse_text":"And he took his staff in his hand, and chose him five smooth stones out of the brook, and put them in a shepherd’s bag which he had, even in a scrip; and his sling was in his hand: and he drew near to the Philistine."},"es":{"prompt":"¿Cuántas piedras lisas escogió David del arroyo?","bible_ref":"1 Samuel 17:40","verse_text":"Tomó su cayado en su mano, y escogióse cinco piedras lisas del arroyo, y púsolas en el saco pastoril y en el zurrón que traía, y con su honda en su mano vase hacia el Filisteo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Cinco"},"fr":{"text":"Cinq"},"en":{"text":"Five"},"es":{"text":"Cinco"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Três"},"fr":{"text":"Trois"},"en":{"text":"Three"},"es":{"text":"Tres"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sete"},"fr":{"text":"Sept"},"en":{"text":"Seven"},"es":{"text":"Siete"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-018","type":"choice","level":"easy","testament":"ot","book":"1SA","chapter":16,"verse_start":23,"verse_end":23,"texts":{"pt":{"prompt":"Que instrumento tocava David para acalmar Saul?","bible_ref":"1 Samuel 16:23","verse_text":"E quando o espírito mau da parte de Deus era sobre Saul, Davi tomava a harpa, e tocava com sua mão; e Saul tinha refrigério, e estava melhor, e o espírito mau se afastava dele."},"fr":{"prompt":"De quel instrument David jouait-il pour soulager Saül ?","bible_ref":"1 Samuel 16:23","verse_text":"Et lorsque l’esprit de Dieu était sur Saül, David prenait la harpe et jouait de sa main; Saül respirait alors plus à l’aise et se trouvait soulagé, et le mauvais esprit se retirait de lui."},"en":{"prompt":"What instrument did David play to refresh Saul?","bible_ref":"1 Samuel 16:23","verse_text":"And it came to pass, when the evil spirit from God was upon Saul, that David took an harp, and played with his hand: so Saul was refreshed, and was well, and the evil spirit departed from him."},"es":{"prompt":"¿Qué instrumento tocaba David para aliviar a Saúl?","bible_ref":"1 Samuel 16:23","verse_text":"Y cuando el espíritu malo de parte de Dios era sobre Saúl, David tomaba el arpa, y tañía con su mano; y Saúl tenía refrigerio, y estaba mejor, y el espíritu malo se apartaba de él."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A harpa"},"fr":{"text":"La harpe"},"en":{"text":"The harp"},"es":{"text":"El arpa"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A trombeta"},"fr":{"text":"La trompette"},"en":{"text":"The trumpet"},"es":{"text":"La trompeta"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O tambor"},"fr":{"text":"Le tambour"},"en":{"text":"The drum"},"es":{"text":"El tambor"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-019","type":"choice","level":"easy","testament":"ot","book":"1SA","chapter":18,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Que filho de Saul amou David como à sua própria alma?","bible_ref":"1 Samuel 18:1","verse_text":"E assim que ele acabou de falar com Saul, a alma de Jônatas se apegou à de Davi, e Jônatas o amou como à sua alma."},"fr":{"prompt":"Quel fils de Saül aima David comme son âme ?","bible_ref":"1 Samuel 18:1","verse_text":"David avait achevé de parler à Saül. Et dès lors l’âme de Jonathan fut attachée à l’âme de David, et Jonathan l’aima comme son âme."},"en":{"prompt":"Which son of Saul loved David as his own soul?","bible_ref":"1 Samuel 18:1","verse_text":"And it came to pass, when he had made an end of speaking unto Saul, that the soul of Jonathan was knit with the soul of David, and Jonathan loved him as his own soul."},"es":{"prompt":"¿Qué hijo de Saúl amó a David como a su alma?","bible_ref":"1 Samuel 18:1","verse_text":"Y así que él hubo acabado de hablar con Saúl, el alma de Jonathán fué ligada con la de David, y amólo Jonathán como á su alma."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Jónatas"},"fr":{"text":"Jonathan"},"en":{"text":"Jonathan"},"es":{"text":"Jonathán"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Absalão"},"fr":{"text":"Absalom"},"en":{"text":"Absalom"},"es":{"text":"Absalom"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Samuel"},"fr":{"text":"Samuel"},"en":{"text":"Samuel"},"es":{"text":"Samuel"}}}]}$json$::jsonb);
