select public.upsert_bank_question($json${"id":"hist2-easy-024","type":"choice","level":"easy","testament":"ot","book":"2SA","chapter":12,"verse_start":24,"verse_end":24,"texts":{"pt":{"prompt":"Que filho de David e Bate-Seba foi amado pelo SENHOR?","bible_ref":"2 Samuel 12:24","verse_text":"E consolou Davi a Bate-Seba sua mulher, e entrando a ela, dormiu com ela; e deu à luz um filho, e chamou seu nome Salomão, ao qual o SENHOR amou:"},"fr":{"prompt":"Quel fils de David et de Bath-Schéba fut aimé de l’Éternel ?","bible_ref":"2 Samuel 12:24","verse_text":"David consola Bath-Schéba, sa femme, et il alla auprès d’elle et coucha avec elle. Elle enfanta un fils qu’il appela Salomon, et qui fut aimé de l’Éternel."},"en":{"prompt":"Which son of David and Bath-sheba did the LORD love?","bible_ref":"2 Samuel 12:24","verse_text":"And David comforted Bath-sheba his wife, and went in unto her, and lay with her: and she bare a son, and he called his name Solomon: and the LORD loved him."},"es":{"prompt":"¿Qué hijo de David y Bath-sheba fue amado por Jehová?","bible_ref":"2 Samuel 12:24","verse_text":"Y consoló David á Bath-sheba su mujer, y entrando á ella, durmió con ella; y parió un hijo, y llamó su nombre Salomón, al cual amó Jehová:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Salomão"},"fr":{"text":"Salomon"},"en":{"text":"Solomon"},"es":{"text":"Salomón"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Absalão"},"fr":{"text":"Absalom"},"en":{"text":"Absalom"},"es":{"text":"Absalom"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Samuel"},"fr":{"text":"Samuel"},"en":{"text":"Samuel"},"es":{"text":"Samuel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-025","type":"choice","level":"easy","testament":"ot","book":"2SA","chapter":5,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Que fortaleza tomou David, que passou a ser a cidade de David?","bible_ref":"2 Samuel 5:7","verse_text":"Porém Davi tomou a fortaleza de Sião, a qual é a cidade de Davi."},"fr":{"prompt":"De quelle forteresse David s’empara-t-il, qui devint la cité de David ?","bible_ref":"2 Samuel 5:7","verse_text":"Mais David s’empara de la forteresse de Sion: c’est la cité de David."},"en":{"prompt":"Which strong hold did David take, which is the city of David?","bible_ref":"2 Samuel 5:7","verse_text":"Nevertheless David took the strong hold of Zion: the same is the city of David."},"es":{"prompt":"¿Qué fortaleza tomó David, que es la ciudad de David?","bible_ref":"2 Samuel 5:7","verse_text":"Empero David tomó la fortaleza de Sión, la cual es la ciudad de David."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Sião"},"fr":{"text":"Sion"},"en":{"text":"Zion"},"es":{"text":"Sión"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Jericó"},"fr":{"text":"Jéricho"},"en":{"text":"Jericho"},"es":{"text":"Jericó"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Hebrom"},"fr":{"text":"Hébron"},"en":{"text":"Hebron"},"es":{"text":"Hebrón"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-026","type":"choice","level":"easy","testament":"ot","book":"2SA","chapter":9,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Por amor de quem prometeu David fazer bem a Mefibosete?","bible_ref":"2 Samuel 9:7","verse_text":"E disse-lhe Davi: Não tenhas temor, porque eu à verdade farei contigo misericórdia por causa de Jônatas teu pai, e te devolverei todas as terras de Saul teu pai; e tu comerás sempre pão à minha mesa."},"fr":{"prompt":"À cause de qui David promit-il de faire du bien à Mephiboscheth ?","bible_ref":"2 Samuel 9:7","verse_text":"David lui dit: Ne crains point, car je veux te faire du bien à cause de Jonathan, ton père. Je te rendrai toutes les terres de Saül, ton père, et tu mangeras toujours à ma table."},"en":{"prompt":"For whose sake did David promise to show kindness to Mephibosheth?","bible_ref":"2 Samuel 9:7","verse_text":"And David said unto him, Fear not: for I will surely shew thee kindness for Jonathan thy father’s sake, and will restore thee all the land of Saul thy father; and thou shalt eat bread at my table continually."},"es":{"prompt":"¿Por amor de quién prometió David hacer misericordia a Mephi-boseth?","bible_ref":"2 Samuel 9:7","verse_text":"Y díjole David: No tengas temor, porque yo á la verdad haré contigo misericordia por amor de Jonathán tu padre, y te haré volver todas las tierras de Saúl tu padre; y tú comerás siempre pan á mi mesa."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"De Jónatas, o seu pai"},"fr":{"text":"De Jonathan, son père"},"en":{"text":"Jonathan, his father"},"es":{"text":"De Jonathán, su padre"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"De Samuel, o profeta"},"fr":{"text":"De Samuel, le prophète"},"en":{"text":"Samuel, the prophet"},"es":{"text":"De Samuel, el profeta"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"De Abner, o general"},"fr":{"text":"D’Abner, le chef de l’armée"},"en":{"text":"Abner, the captain"},"es":{"text":"De Abner, el general"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-027","type":"choice","level":"easy","testament":"ot","book":"2SA","chapter":12,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"O que disse David a Natã depois de ouvir a sua história?","bible_ref":"2 Samuel 12:13","verse_text":"Então disse Davi a Natã: Pequei contra o SENHOR. E Natã disse a Davi: Também o SENHOR removeu teu pecado: não morrerás."},"fr":{"prompt":"Que dit David à Nathan après avoir entendu son histoire ?","bible_ref":"2 Samuel 12:13","verse_text":"David dit à Nathan: J’ai péché contre l’Éternel! Et Nathan dit à David: L’Éternel pardonne ton péché, tu ne mourras point."},"en":{"prompt":"What did David say to Nathan after hearing his story?","bible_ref":"2 Samuel 12:13","verse_text":"And David said unto Nathan, I have sinned against the LORD. And Nathan said unto David, The LORD also hath put away thy sin; thou shalt not die."},"es":{"prompt":"¿Qué dijo David a Nathán después de oír su historia?","bible_ref":"2 Samuel 12:13","verse_text":"Entonces dijo David á Nathán: Pequé contra Jehová. Y Nathán dijo á David: También Jehová ha remitido tu pecado: no morirás."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"«Pequei contra o SENHOR»"},"fr":{"text":"« J’ai péché contre l’Éternel »"},"en":{"text":"“I have sinned against the LORD”"},"es":{"text":"«Pequé contra Jehová»"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"«Eu estou inocente»"},"fr":{"text":"« Je suis innocent »"},"en":{"text":"“I am innocent”"},"es":{"text":"«Yo soy inocente»"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"«Vou castigar-te»"},"fr":{"text":"« Je vais te punir »"},"en":{"text":"“I will punish you”"},"es":{"text":"«Te castigaré»"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-easy-028","type":"order","level":"easy","testament":"ot","book":"2SA","chapter":5,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"2 Samuel 5:3","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"2 Samuel 5:3","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"2 Samuel 5:3","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"2 Samuel 5:3","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"David é ungido rei sobre Israel","ref":"2 Samuel 5:3"},"fr":{"text":"David est oint roi sur Israël","ref":"2 Samuel 5:3"},"en":{"text":"David is anointed king over Israel","ref":"2 Samuel 5:3"},"es":{"text":"David es ungido rey sobre Israel","ref":"2 Samuel 5:3"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A arca sobe com som de trombeta","ref":"2 Samuel 6:15"},"fr":{"text":"L’arche monte au son des trompettes","ref":"2 Samuel 6:15"},"en":{"text":"The ark is brought up with trumpets","ref":"2 Samuel 6:15"},"es":{"text":"El arca sube con sonido de trompeta","ref":"2 Samuel 6:15"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"David vê uma mulher desde o terraço","ref":"2 Samuel 11:2"},"fr":{"text":"David voit une femme depuis le toit","ref":"2 Samuel 11:2"},"en":{"text":"David sees a woman from the roof","ref":"2 Samuel 11:2"},"es":{"text":"David ve a una mujer desde el terrado","ref":"2 Samuel 11:2"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O SENHOR envia Natã a David","ref":"2 Samuel 12:1"},"fr":{"text":"L’Éternel envoie Nathan vers David","ref":"2 Samuel 12:1"},"en":{"text":"The LORD sends Nathan to David","ref":"2 Samuel 12:1"},"es":{"text":"Jehová envía a Nathán a David","ref":"2 Samuel 12:1"}}}]}$json$::jsonb);
