select public.upsert_bank_question($json${"id":"hist2-easy-030","type":"verse","level":"easy","testament":"ot","book":"2SA","chapter":22,"verse_start":29,"verse_end":29,"texts":{"pt":{"prompt":"Porque tu és minha _____, ó SENHOR; o SENHOR dá luz às minhas trevas.","bible_ref":"2 Samuel 22:29","verse_text":"Porque tu és minha lâmpada, ó SENHOR; o SENHOR dá luz às minhas trevas."},"fr":{"prompt":"Oui, tu es ma _____, ô Éternel! L’Éternel éclaire mes ténèbres.","bible_ref":"2 Samuel 22:29","verse_text":"Oui, tu es ma lumière, ô Éternel! L’Éternel éclaire mes ténèbres."},"en":{"prompt":"For thou art my _____, O LORD: and the LORD will lighten my darkness.","bible_ref":"2 Samuel 22:29","verse_text":"For thou art my lamp, O LORD: and the LORD will lighten my darkness."},"es":{"prompt":"Porque tú eres mi _____, oh Jehová: Jehová da luz á mis tinieblas.","bible_ref":"2 Samuel 22:29","verse_text":"Porque tú eres mi lámpara, oh Jehová: Jehová da luz á mis tinieblas."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"coroa"},"fr":{"text":"couronne"},"en":{"text":"crown"},"es":{"text":"corona"}}},{"position":2,"is_correct":true,"texts":{"pt":{"text":"lâmpada"},"fr":{"text":"lumière"},"en":{"text":"lamp"},"es":{"text":"lámpara"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"espada"},"fr":{"text":"épée"},"en":{"text":"sword"},"es":{"text":"espada"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"casa"},"fr":{"text":"maison"},"en":{"text":"house"},"es":{"text":"casa"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-001","type":"choice","level":"medium","testament":"ot","book":"JOS","chapter":5,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Segundo Josué 5:12, o que cessou quando Israel começou a comer dos frutos da terra?","bible_ref":"Josué 5:12","verse_text":"E o maná cessou o dia seguinte, desde que começaram a comer do fruto da terra: e os filhos de Israel nunca mais tiveram maná, mas sim que comeram dos frutos da terra de Canaã aquele ano."},"fr":{"prompt":"Selon Josué 5:12, qu’est-ce qui cessa quand Israël mangea des produits du pays ?","bible_ref":"Josué 5:12","verse_text":"La manne cessa le lendemain de la Pâque, quand ils mangèrent du blé du pays; les enfants d’Israël n’eurent plus de manne, et ils mangèrent des produits du pays de Canaan cette année-là."},"en":{"prompt":"According to Joshua 5:12, what ceased when Israel ate of the produce of the land?","bible_ref":"Joshua 5:12","verse_text":"And the manna ceased on the morrow after they had eaten of the old corn of the land; neither had the children of Israel manna any more; but they did eat of the fruit of the land of Canaan that year."},"es":{"prompt":"Según Josué 5:12, ¿qué cesó cuando Israel comenzó a comer del fruto de la tierra?","bible_ref":"Josué 5:12","verse_text":"Y el maná cesó el día siguiente, desde que comenzaron á comer del fruto de la tierra: y los hijos de Israel nunca más tuvieron maná, sino que comieron de los frutos de la tierra de Canaán aquel año."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O maná"},"fr":{"text":"La manne"},"en":{"text":"The manna"},"es":{"text":"El maná"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"As codornizes"},"fr":{"text":"Les cailles"},"en":{"text":"The quails"},"es":{"text":"Las codornices"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A água da rocha"},"fr":{"text":"L’eau du rocher"},"en":{"text":"The water from the rock"},"es":{"text":"El agua de la peña"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-002","type":"choice","level":"medium","testament":"ot","book":"JOS","chapter":7,"verse_start":21,"verse_end":21,"texts":{"pt":{"prompt":"O que escondeu Acã debaixo da terra, no meio da sua tenda?","bible_ref":"Josué 7:21","verse_text":"Que vi entre os despojos um manto babilônico muito bom, e duzentos siclos de prata, e uma barra de ouro de peso de cinquenta siclos; o qual cobicei, e tomei: e eis que está escondido debaixo da terra no meio de minha tenda, e o dinheiro debaixo dele."},"fr":{"prompt":"Qu’est-ce qu’Acan cacha dans la terre, au milieu de sa tente ?","bible_ref":"Josué 7:21","verse_text":"J’ai vu dans le butin un beau manteau de Schinear, deux cents sicles d’argent, et un lingot d’or du poids de cinquante sicles; je les ai convoités, et je les ai pris; ils sont cachés dans la terre au milieu de ma tente, et l’argent est dessous."},"en":{"prompt":"What did Achan hide in the earth in the midst of his tent?","bible_ref":"Joshua 7:21","verse_text":"When I saw among the spoils a goodly Babylonish garment, and two hundred shekels of silver, and a wedge of gold of fifty shekels weight, then I coveted them, and took them; and, behold, they are hid in the earth in the midst of my tent, and the silver under it."},"es":{"prompt":"¿Qué escondió Achân debajo de tierra, en medio de su tienda?","bible_ref":"Josué 7:21","verse_text":"Que vi entre los despojos un manto babilónico muy bueno, y doscientos siclos de plata, y un changote de oro de peso de cincuenta siclos; lo cual codicié, y tomé: y he aquí que está escondido debajo de tierra en el medio de mi tienda, y el dinero debajo de ello."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um manto, prata e uma barra de ouro"},"fr":{"text":"Un manteau, de l’argent et un lingot d’or"},"en":{"text":"A garment, silver and a wedge of gold"},"es":{"text":"Un manto, plata y una barra de oro"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Ídolos de pedra"},"fr":{"text":"Des idoles de pierre"},"en":{"text":"Idols of stone"},"es":{"text":"Ídolos de piedra"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"As armas dos soldados de Jericó"},"fr":{"text":"Les armes des soldats de Jéricho"},"en":{"text":"The weapons of Jericho’s soldiers"},"es":{"text":"Las armas de los soldados de Jericó"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-003","type":"choice","level":"medium","testament":"ot","book":"JOS","chapter":9,"verse_start":3,"verse_end":4,"texts":{"pt":{"prompt":"Para enganar Josué, o que levaram sobre os jumentos os moradores de Gibeão?","bible_ref":"Josué 9:3-4","verse_text":"Mas os moradores de Gibeão, quando ouviram o que Josué havia feito a Jericó e a Ai, Eles usaram também de astúcia; pois foram e fingiram-se embaixadores, e tomaram sacos velhos sobre seus asnos, e odres velhos de vinho, rasgados e remendados,"},"fr":{"prompt":"Pour tromper Josué, que prirent pour leurs ânes les habitants de Gabaon ?","bible_ref":"Josué 9:3-4","verse_text":"Les habitants de Gabaon, de leur côté, lorsqu’ils apprirent de quelle manière Josué avait traité Jéricho et Aï, eurent recours à la ruse, et se mirent en route avec des provisions de voyage. Ils prirent de vieux sacs pour leurs ânes, et de vieilles outres à vin déchirées et recousues,"},"en":{"prompt":"To deceive Joshua, what did the inhabitants of Gibeon take upon their asses?","bible_ref":"Joshua 9:3-4","verse_text":"And when the inhabitants of Gibeon heard what Joshua had done unto Jericho and to Ai, They did work wilily, and went and made as if they had been ambassadors, and took old sacks upon their asses, and wine bottles, old, and rent, and bound up;"},"es":{"prompt":"Para engañar a Josué, ¿qué llevaron sobre sus asnos los moradores de Gabaón?","bible_ref":"Josué 9:3-4","verse_text":"Mas los moradores de Gabaón, como oyeron lo que Josué había hecho á Jericó y á Hai, Ellos usaron también de astucia; pues fueron y fingiéronse embajadores, y tomaron sacos viejos sobre sus asnos, y cueros viejos de vino, rotos y remendados,"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Sacos velhos e odres de vinho rasgados"},"fr":{"text":"De vieux sacs et de vieilles outres déchirées"},"en":{"text":"Old sacks and old, rent wine bottles"},"es":{"text":"Sacos viejos y cueros de vino rotos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Ouro e prata para Josué"},"fr":{"text":"De l’or et de l’argent pour Josué"},"en":{"text":"Gold and silver for Joshua"},"es":{"text":"Oro y plata para Josué"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Armas novas"},"fr":{"text":"Des armes neuves"},"en":{"text":"New weapons"},"es":{"text":"Armas nuevas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-004","type":"choice","level":"medium","testament":"ot","book":"JOS","chapter":5,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"O que mandou o príncipe do exército do SENHOR a Josué tirar?","bible_ref":"Josué 5:15","verse_text":"E o Príncipe do exército do SENHOR respondeu a Josué: Tira teus sapatos de teus pés; porque o lugar onde estás é santo. E Josué o fez assim."},"fr":{"prompt":"Qu’est-ce que le chef de l’armée de l’Éternel ordonna à Josué d’ôter ?","bible_ref":"Josué 5:15","verse_text":"Et le chef de l’armée de l’Éternel dit à Josué: Ote tes souliers de tes pieds, car le lieu sur lequel tu te tiens est saint. Et Josué fit ainsi."},"en":{"prompt":"What did the captain of the LORD’s host tell Joshua to loose?","bible_ref":"Joshua 5:15","verse_text":"And the captain of the LORD’s host said unto Joshua, Loose thy shoe from off thy foot; for the place whereon thou standest is holy. And Joshua did so."},"es":{"prompt":"¿Qué mandó el Príncipe del ejército de Jehová a Josué que se quitara?","bible_ref":"Josué 5:15","verse_text":"Y el Príncipe del ejército de Jehová respondió á Josué: Quita tus zapatos de tus pies; porque el lugar donde estás es santo. Y Josué lo hizo así."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Os sapatos dos pés"},"fr":{"text":"Les souliers de ses pieds"},"en":{"text":"The shoe from his foot"},"es":{"text":"Los zapatos de sus pies"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O capacete"},"fr":{"text":"Son casque"},"en":{"text":"His helmet"},"es":{"text":"Su yelmo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A capa"},"fr":{"text":"Son manteau"},"en":{"text":"His cloak"},"es":{"text":"Su capa"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-005","type":"order","level":"medium","testament":"ot","book":"JOS","chapter":7,"verse_start":18,"verse_end":18,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"Josué 7:18","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"Josué 7:18","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"Joshua 7:18","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"Josué 7:18","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Acã é apanhado entre o povo","ref":"Josué 7:18"},"fr":{"text":"Acan est désigné parmi le peuple","ref":"Josué 7:18"},"en":{"text":"Achan is taken among the people","ref":"Joshua 7:18"},"es":{"text":"Achân es tomado entre el pueblo","ref":"Josué 7:18"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Josué queima a cidade de Ai","ref":"Josué 8:28"},"fr":{"text":"Josué brûle la ville d’Aï","ref":"Josué 8:28"},"en":{"text":"Joshua burns the city of Ai","ref":"Joshua 8:28"},"es":{"text":"Josué quema la ciudad de Hai","ref":"Josué 8:28"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Josué diz ao sol que se detenha","ref":"Josué 10:12"},"fr":{"text":"Josué dit au soleil de s’arrêter","ref":"Josué 10:12"},"en":{"text":"Joshua tells the sun to stand still","ref":"Joshua 10:12"},"es":{"text":"Josué dice al sol que se detenga","ref":"Josué 10:12"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Josué toma toda a terra","ref":"Josué 11:23"},"fr":{"text":"Josué s’empare de tout le pays","ref":"Josué 11:23"},"en":{"text":"Joshua takes the whole land","ref":"Joshua 11:23"},"es":{"text":"Josué toma toda la tierra","ref":"Josué 11:23"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-006","type":"verse","level":"medium","testament":"ot","book":"JOS","chapter":1,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"O livro desta lei nunca se apartará de tua boca: antes de dia e de noite _____ nele, para que guardes e faças conforme tudo o que nele está escrito: porque então farás prosperar teu caminho, e tudo te sairá bem.","bible_ref":"Josué 1:8","verse_text":"O livro desta lei nunca se apartará de tua boca: antes de dia e de noite meditarás nele, para que guardes e faças conforme tudo o que nele está escrito: porque então farás prosperar teu caminho, e tudo te sairá bem."},"fr":{"prompt":"Que ce livre de la loi ne s’éloigne point de ta bouche; _____-le jour et nuit, pour agir fidèlement selon tout ce qui y est écrit; car c’est alors que tu auras du succès dans tes entreprises, c’est alors que tu réussiras.","bible_ref":"Josué 1:8","verse_text":"Que ce livre de la loi ne s’éloigne point de ta bouche; médite-le jour et nuit, pour agir fidèlement selon tout ce qui y est écrit; car c’est alors que tu auras du succès dans tes entreprises, c’est alors que tu réussiras."},"en":{"prompt":"This book of the law shall not depart out of thy mouth; but thou shalt _____ therein day and night, that thou mayest observe to do according to all that is written therein: for then thou shalt make thy way prosperous, and then thou shalt have good success.","bible_ref":"Joshua 1:8","verse_text":"This book of the law shall not depart out of thy mouth; but thou shalt meditate therein day and night, that thou mayest observe to do according to all that is written therein: for then thou shalt make thy way prosperous, and then thou shalt have good success."},"es":{"prompt":"El libro de aquesta ley nunca se apartará de tu boca: antes de día y de noche _____ en él, para que guardes y hagas conforme á todo lo que en él está escrito: porque entonces harás prosperar tu camino, y todo te saldrá bien.","bible_ref":"Josué 1:8","verse_text":"El libro de aquesta ley nunca se apartará de tu boca: antes de día y de noche meditarás en él, para que guardes y hagas conforme á todo lo que en él está escrito: porque entonces harás prosperar tu camino, y todo te saldrá bien."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"meditarás"},"fr":{"text":"médite"},"en":{"text":"meditate"},"es":{"text":"meditarás"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"escreverás"},"fr":{"text":"écris"},"en":{"text":"write"},"es":{"text":"escribirás"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"cantarás"},"fr":{"text":"chante"},"en":{"text":"sing"},"es":{"text":"cantarás"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"lerás"},"fr":{"text":"lis"},"en":{"text":"read"},"es":{"text":"leerás"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-007","type":"verse","level":"medium","testament":"ot","book":"JOS","chapter":21,"verse_start":45,"verse_end":45,"texts":{"pt":{"prompt":"Não faltou palavra de todas as _____ coisas que o SENHOR falou à casa de Israel; tudo se cumpriu.","bible_ref":"Josué 21:45","verse_text":"Não faltou palavra de todas as boas coisas que o SENHOR falou à casa de Israel; tudo se cumpriu."},"fr":{"prompt":"De toutes les _____ paroles que l’Éternel avait dites à la maison d’Israël, aucune ne resta sans effet: toutes s’accomplirent.","bible_ref":"Josué 21:45","verse_text":"De toutes les bonnes paroles que l’Éternel avait dites à la maison d’Israël, aucune ne resta sans effet: toutes s’accomplirent."},"en":{"prompt":"There failed not ought of any _____ thing which the LORD had spoken unto the house of Israel; all came to pass.","bible_ref":"Joshua 21:45","verse_text":"There failed not ought of any good thing which the LORD had spoken unto the house of Israel; all came to pass."},"es":{"prompt":"No faltó palabra de todas las _____ que habló Jehová á la casa de Israel; todo se cumplió.","bible_ref":"Josué 21:45","verse_text":"No faltó palabra de todas las buenas que habló Jehová á la casa de Israel; todo se cumplió."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"boas"},"fr":{"text":"bonnes"},"en":{"text":"good"},"es":{"text":"buenas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"grandes"},"fr":{"text":"grandes"},"en":{"text":"great"},"es":{"text":"grandes"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"santas"},"fr":{"text":"saintes"},"en":{"text":"holy"},"es":{"text":"santas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"novas"},"fr":{"text":"nouvelles"},"en":{"text":"new"},"es":{"text":"nuevas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-008","type":"choice","level":"medium","testament":"ot","book":"JDG","chapter":4,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Segundo Débora, nas mãos de quem ia o SENHOR entregar Sísera?","bible_ref":"Juízes 4:9","verse_text":"E ela disse: Irei contigo; mas não será tua honra no caminho que vais; porque por mão de mulher venderá o SENHOR a Sísera. E levantando-se Débora foi com Baraque a Quedes."},"fr":{"prompt":"Selon Débora, entre les mains de qui l’Éternel allait-il livrer Sisera ?","bible_ref":"Juges 4:9","verse_text":"Elle répondit: J’irai bien avec toi; mais tu n’auras point de gloire sur la voie où tu marches, car l’Éternel livrera Sisera entre les mains d’une femme. Et Débora se leva, et elle se rendit avec Barak à Kédesch."},"en":{"prompt":"According to Deborah, into whose hand would the LORD sell Sisera?","bible_ref":"Judges 4:9","verse_text":"And she said, I will surely go with thee: notwithstanding the journey that thou takest shall not be for thine honour; for the LORD shall sell Sisera into the hand of a woman. And Deborah arose, and went with Barak to Kedesh."},"es":{"prompt":"Según Débora, ¿en mano de quién iba Jehová a entregar a Sísara?","bible_ref":"Jueces 4:9","verse_text":"Y ella dijo: Iré contigo; mas no será tu honra en el camino que vas; porque en mano de mujer venderá Jehová á Sísara. Y levantándose Débora fué con Barac á Cedes."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"De uma mulher"},"fr":{"text":"D’une femme"},"en":{"text":"A woman"},"es":{"text":"De una mujer"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"De Baraque"},"fr":{"text":"De Barak"},"en":{"text":"Barak"},"es":{"text":"De Barac"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"De um rei estrangeiro"},"fr":{"text":"D’un roi étranger"},"en":{"text":"A foreign king"},"es":{"text":"De un rey extranjero"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-009","type":"choice","level":"medium","testament":"ot","book":"JDG","chapter":6,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"O que estava Gideão a fazer quando veio o anjo do SENHOR?","bible_ref":"Juízes 6:11","verse_text":"E veio o anjo do SENHOR, e sentou-se debaixo do carvalho que está em Ofra, o qual era de Joás abiezrita; e seu filho Gideão estava malhando o trigo na prensa de uvas, para fazê-lo esconder dos midianitas."},"fr":{"prompt":"Que faisait Gédéon quand vint l’ange de l’Éternel ?","bible_ref":"Juges 6:11","verse_text":"Puis vint l’ange de l’Éternel, et il s’assit sous le térébinthe d’Ophra, qui appartenait à Joas, de la famille d’Abiézer. Gédéon, son fils, battait du froment au pressoir, pour le mettre à l’abri de Madian."},"en":{"prompt":"What was Gideon doing when the angel of the LORD came?","bible_ref":"Judges 6:11","verse_text":"And there came an angel of the LORD, and sat under an oak which was in Ophrah, that pertained unto Joash the Abi-ezrite: and his son Gideon threshed wheat by the winepress, to hide it from the Midianites."},"es":{"prompt":"¿Qué estaba haciendo Gedeón cuando vino el ángel de Jehová?","bible_ref":"Jueces 6:11","verse_text":"Y vino el ángel de Jehová, y sentóse debajo del alcornoque que está en Ophra, el cual era de Joas Abiezerita; y su hijo Gedeón estaba sacudiendo el trigo en el lagar, para hacerlo esconder de los Madianitas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A malhar trigo junto à prensa de uvas"},"fr":{"text":"Il battait du froment au pressoir"},"en":{"text":"Threshing wheat by the winepress"},"es":{"text":"Sacudiendo el trigo en el lagar"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A guardar as ovelhas do pai"},"fr":{"text":"Il gardait les brebis de son père"},"en":{"text":"Keeping his father’s sheep"},"es":{"text":"Apacentando las ovejas de su padre"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A pescar no rio"},"fr":{"text":"Il pêchait dans le fleuve"},"en":{"text":"Fishing in the river"},"es":{"text":"Pescando en el río"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-010","type":"choice","level":"medium","testament":"ot","book":"JDG","chapter":7,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Depois de partirem os medrosos, quantos homens ficaram com Gideão?","bible_ref":"Juízes 7:3","verse_text":"Agora, pois, proclama aos ouvidos do povo, dizendo: Aquele que teme e se estremece, volte e retire-se do monte de Gileade. E do povo voltaram vinte e dois mil; e restaram dez mil."},"fr":{"prompt":"Après le départ des craintifs, combien d’hommes restèrent avec Gédéon ?","bible_ref":"Juges 7:3","verse_text":"Publie donc ceci aux oreilles du peuple: Que celui qui est craintif et qui a peur s’en retourne et s’éloigne de la montagne de Galaad. Vingt-deux mille hommes parmi le peuple s’en retournèrent, et il en resta dix mille."},"en":{"prompt":"After the fearful had departed, how many men remained with Gideon?","bible_ref":"Judges 7:3","verse_text":"Now therefore go to, proclaim in the ears of the people, saying, Whosoever is fearful and afraid, let him return and depart early from mount Gilead. And there returned of the people twenty and two thousand; and there remained ten thousand."},"es":{"prompt":"Después de irse los medrosos, ¿cuántos hombres quedaron con Gedeón?","bible_ref":"Jueces 7:3","verse_text":"Haz pues ahora pregonar, que lo oiga el pueblo, diciendo: El que teme y se estremece, madrugue y vuélvase desde el monte de Galaad. Y volviéronse de los del pueblo veintidós mil: y quedaron diez mil."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Dez mil"},"fr":{"text":"Dix mille"},"en":{"text":"Ten thousand"},"es":{"text":"Diez mil"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Vinte e dois mil"},"fr":{"text":"Vingt-deux mille"},"en":{"text":"Twenty-two thousand"},"es":{"text":"Veintidós mil"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Mil"},"fr":{"text":"Mille"},"en":{"text":"One thousand"},"es":{"text":"Mil"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-011","type":"choice","level":"medium","testament":"ot","book":"JDG","chapter":13,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Segundo o anjo, o que nunca devia passar sobre a cabeça do filho que ia nascer?","bible_ref":"Juízes 13:5","verse_text":"Porque tu te farás grávida, e darás à luz um filho: e não subirá navalha sobre sua cabeça, porque aquele menino será nazireu a Deus desde o ventre, e ele começará a salvar a Israel da mão dos filisteus."},"fr":{"prompt":"Selon l’ange, qu’est-ce qui ne devait jamais passer sur la tête du fils à naître ?","bible_ref":"Juges 13:5","verse_text":"Car tu vas devenir enceinte et tu enfanteras un fils. Le rasoir ne passera point sur sa tête, parce que cet enfant sera consacré à Dieu dès le ventre de sa mère; et ce sera lui qui commencera à délivrer Israël de la main des Philistins."},"en":{"prompt":"According to the angel, what must never come on the head of the son to be born?","bible_ref":"Judges 13:5","verse_text":"For, lo, thou shalt conceive, and bear a son; and no razor shall come on his head: for the child shall be a Nazarite unto God from the womb: and he shall begin to deliver Israel out of the hand of the Philistines."},"es":{"prompt":"Según el ángel, ¿qué nunca debía subir sobre la cabeza del hijo que iba a nacer?","bible_ref":"Jueces 13:5","verse_text":"Porque tú te harás embarazada, y parirás un hijo: y no subirá navaja sobre su cabeza, porque aquel niño será Nazareo á Dios desde el vientre, y él comenzará á salvar á Israel de mano de los Filisteos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A navalha"},"fr":{"text":"Le rasoir"},"en":{"text":"A razor"},"es":{"text":"La navaja"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A coroa"},"fr":{"text":"La couronne"},"en":{"text":"A crown"},"es":{"text":"La corona"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O capacete"},"fr":{"text":"Le casque"},"en":{"text":"A helmet"},"es":{"text":"El yelmo"}}}]}$json$::jsonb);
