select public.upsert_bank_question($json${"id":"hist2-medium-013","type":"order","level":"medium","testament":"ot","book":"JDG","chapter":14,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"Juízes 14:12","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"Juges 14:12","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"Judges 14:12","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"Jueces 14:12","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Sansão propõe um enigma no banquete","ref":"Juízes 14:12"},"fr":{"text":"Samson propose une énigme au festin","ref":"Juges 14:12"},"en":{"text":"Samson puts forth a riddle at the feast","ref":"Judges 14:12"},"es":{"text":"Samsón propone un enigma en el banquete","ref":"Jueces 14:12"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Sansão apanha trezentas raposas","ref":"Juízes 15:4"},"fr":{"text":"Samson attrape trois cents renards","ref":"Juges 15:4"},"en":{"text":"Samson catches three hundred foxes","ref":"Judges 15:4"},"es":{"text":"Samsón coge trescientas zorras","ref":"Jueces 15:4"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sansão leva as portas da cidade ao ombro","ref":"Juízes 16:3"},"fr":{"text":"Samson emporte les portes de la ville","ref":"Juges 16:3"},"en":{"text":"Samson carries off the doors of the city gate","ref":"Judges 16:3"},"es":{"text":"Samsón se lleva al hombro las puertas de la ciudad","ref":"Jueces 16:3"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Os filisteus tiram os olhos a Sansão","ref":"Juízes 16:21"},"fr":{"text":"Les Philistins crèvent les yeux de Samson","ref":"Juges 16:21"},"en":{"text":"The Philistines put out Samson’s eyes","ref":"Judges 16:21"},"es":{"text":"Los filisteos sacan los ojos a Samsón","ref":"Ju