select public.upsert_bank_question($json${"id":"hist2-medium-014","type":"verse","level":"medium","testament":"ot","book":"JDG","chapter":7,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"E os três esquadrões tocaram as trombetas, e quebrando os cântaros tomaram nas mãos esquerdas as tochas, e nas direitas as trombetas com que tocavam, e deram grito: A _____ do SENHOR e de Gideão!","bible_ref":"Juízes 7:20","verse_text":"E os três esquadrões tocaram as trombetas, e quebrando os cântaros tomaram nas mãos esquerdas as tochas, e nas direitas as trombetas com que tocavam, e deram grito: A espada do SENHOR e de Gideão!"},"fr":{"prompt":"Les trois corps sonnèrent de la trompette, et brisèrent les cruches; ils saisirent de la main gauche les flambeaux et de la main droite les trompettes pour sonner, et ils s’écrièrent: _____ pour l’Éternel et pour Gédéon!","bible_ref":"Juges 7:20","verse_text":"Les trois corps sonnèrent de la trompette, et brisèrent les cruches; ils saisirent de la main gauche les flambeaux et de la main droite les trompettes pour sonner, et ils s’écrièrent: Épée pour l’Éternel et pour Gédéon!"},"en":{"prompt":"And the three companies blew the trumpets, and brake the pitchers, and held the lamps in their left hands, and the trumpets in their right hands to blow withal: and they cried, The _____ of the LORD, and of Gideon.","bible_ref":"Judges 7:20","verse_text":"And the three companies blew the trumpets, and brake the pitchers, and held the lamps in their left hands, and the trumpets in their right hands to blow withal: and they cried, The sword of the LORD, and of Gideon."},"es":{"prompt":"Y los tres escuadrones tocaron las bocinas, y quebrando los cántaros tomaron en las manos izquierdas las teas, y en las derechas los cuernos con que tañían, y dieron grita: ¡La _____ de Jehová y de Gedeón!","bible_ref":"Jueces 7:20","verse_text":"Y los tres escuadrones tocaron las bocinas, y quebrando los cántaros tomaron en las manos izquierdas las teas, y en las derechas los cuernos con que tañían, y dieron grita: ¡La espada de Jehová y de Gedeón!"}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"lança"},"fr":{"text":"lance"},"en":{"text":"spear"},"es":{"text":"lanza"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"glória"},"fr":{"text":"gloire"},"en":{"text":"glory"},"es":{"text":"gloria"}}},{"position":3,"is_correct":true,"texts":{"pt":{"text":"espada"},"fr":{"text":"épée"},"en":{"text":"sword"},"es":{"text":"espada"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"vitória"},"fr":{"text":"victoire"},"en":{"text":"victory"},"es":{"text":"victoria"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-015","type":"choice","level":"medium","testament":"ot","book":"RUT","chapter":1,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"Que nome pediu Noemi que lhe chamassem?","bible_ref":"Rute 1:20","verse_text":"E ela lhes respondia: Não me chameis Noemi, mas sim me chamai Mara: porque em grande amargura me pôs o Todo-Poderoso."},"fr":{"prompt":"Comment Naomi demanda-t-elle qu’on l’appelle ?","bible_ref":"Ruth 1:20","verse_text":"Elle leur dit: Ne m’appelez pas Naomi; appelez-moi Mara, car le Tout-Puissant m’a remplie d’amertume."},"en":{"prompt":"What did Naomi ask to be called?","bible_ref":"Ruth 1:20","verse_text":"And she said unto them, Call me not Naomi, call me Mara: for the Almighty hath dealt very bitterly with me."},"es":{"prompt":"¿Cómo pidió Noemi que la llamaran?","bible_ref":"Rut 1:20","verse_text":"Y ella les respondía: No me llaméis Noemi, sino llamadme Mara: porque en grande amargura me ha puesto el Todopoderoso."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Mara"},"fr":{"text":"Mara"},"en":{"text":"Mara"},"es":{"text":"Mara"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Penina"},"fr":{"text":"Peninna"},"en":{"text":"Peninnah"},"es":{"text":"Peninna"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Lia"},"fr":{"text":"Léa"},"en":{"text":"Leah"},"es":{"text":"Lea"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-016","type":"choice","level":"medium","testament":"ot","book":"RUT","chapter":1,"verse_start":22,"verse_end":22,"texts":{"pt":{"prompt":"Em que altura chegaram Noemi e Rute a Belém?","bible_ref":"Rute 1:22","verse_text":"Assim voltou Noemi e Rute moabita sua nora com ela; voltou dos campos de Moabe, e chegaram a Belém no princípio da colheita das cevadas."},"fr":{"prompt":"À quel moment Naomi et Ruth arrivèrent-elles à Bethléhem ?","bible_ref":"Ruth 1:22","verse_text":"Ainsi revinrent du pays de Moab Naomi et sa belle-fille, Ruth la Moabite. Elles arrivèrent à Bethléhem au commencement de la moisson des orges."},"en":{"prompt":"At what time did Naomi and Ruth come to Beth-lehem?","bible_ref":"Ruth 1:22","verse_text":"So Naomi returned, and Ruth the Moabitess, her daughter in law, with her, which returned out of the country of Moab: and they came to Beth-lehem in the beginning of barley harvest."},"es":{"prompt":"¿En qué tiempo llegaron Noemi y Ruth a Beth-lehem?","bible_ref":"Rut 1:22","verse_text":"Así volvió Noemi y Ruth Moabita su nuera con ella; volvió de los campos de Moab, y llegaron á Beth-lehem en el principio de la siega de las cebadas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"No princípio da colheita da cevada"},"fr":{"text":"Au commencement de la moisson des orges"},"en":{"text":"In the beginning of barley harvest"},"es":{"text":"En el principio de la siega de las cebadas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Na época da vindima"},"fr":{"text":"Au temps des vendanges"},"en":{"text":"At the time of the grape harvest"},"es":{"text":"En el tiempo de la vendimia"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"No meio do inverno"},"fr":{"text":"Au milieu de l’hiver"},"en":{"text":"In the middle of winter"},"es":{"text":"En medio del invierno"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-017","type":"choice","level":"medium","testament":"ot","book":"RUT","chapter":3,"verse_start":7,"verse_end":8,"texts":{"pt":{"prompt":"Depois de Boaz se deitar junto ao monte de cereal, onde se deitou Rute?","bible_ref":"Rute 3:7-8","verse_text":"E quando Boaz havia comido e bebido, e seu coração esteve contente, retirou-se para dormir a um lado do amontoado. Então ela veio caladamente, e revelou os pés, e deitou-se. E aconteceu, que à meia noite se estremeceu aquele homem, e apalpou: e eis que, a mulher que estava deitada a seus pés."},"fr":{"prompt":"Après que Boaz se fut couché près du tas de gerbes, où Ruth se coucha-t-elle ?","bible_ref":"Ruth 3:7-8","verse_text":"Boaz mangea et but, et son cœur était joyeux. Il alla se coucher à l’extrémité d’un tas de gerbes. Ruth vint alors tout doucement, découvrit ses pieds, et se coucha. Au milieu de la nuit, cet homme eut une frayeur; il se pencha, et voici, une femme était couchée à ses pieds."},"en":{"prompt":"After Boaz lay down at the end of the heap of corn, where did Ruth lie down?","bible_ref":"Ruth 3:7-8","verse_text":"And when Boaz had eaten and drunk, and his heart was merry, he went to lie down at the end of the heap of corn: and she came softly, and uncovered his feet, and laid her down. And it came to pass at midnight, that the man was afraid, and turned himself: and, behold, a woman lay at his feet."},"es":{"prompt":"Después de que Booz se acostó junto al montón, ¿dónde se acostó Ruth?","bible_ref":"Rut 3:7-8","verse_text":"Y como Booz hubo comido y bebido, y su corazón estuvo contento, retiróse á dormir á un lado del montón. Entonces ella vino calladamente, y descubrió los pies, y acostóse. Y aconteció, que á la media noche se estremeció aquel hombre, y palpó: y he aquí, la mujer que estaba acostada á sus pies."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Aos pés de Boaz"},"fr":{"text":"Aux pieds de Boaz"},"en":{"text":"At Boaz’s feet"},"es":{"text":"A los pies de Booz"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"À porta da cidade"},"fr":{"text":"À la porte de la ville"},"en":{"text":"At the gate of the city"},"es":{"text":"A la puerta de la ciudad"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Junto de Noemi, em casa"},"fr":{"text":"Près de Naomi, à la maison"},"en":{"text":"Beside Naomi, at home"},"es":{"text":"Junto a Noemi, en casa"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-018","type":"order","level":"medium","testament":"ot","book":"RUT","chapter":1,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"Rute 1:3","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"Ruth 1:3","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"Ruth 1:3","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"Rut 1:3","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Morre Elimeleque, marido de Noemi","ref":"Rute 1:3"},"fr":{"text":"Élimélec, mari de Naomi, meurt","ref":"Ruth 1:3"},"en":{"text":"Elimelech, Naomi’s husband, dies","ref":"Ruth 1:3"},"es":{"text":"Muere Elimelech, marido de Noemi","ref":"Rut 1:3"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Orfa beija a sogra e despede-se","ref":"Rute 1:14"},"fr":{"text":"Orpa embrasse sa belle-mère","ref":"Ruth 1:14"},"en":{"text":"Orpah kisses her mother-in-law","ref":"Ruth 1:14"},"es":{"text":"Orpha besa a su suegra","ref":"Rut 1:14"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Boaz pede a Rute que fique no seu campo","ref":"Rute 2:8"},"fr":{"text":"Boaz dit à Ruth de rester dans son champ","ref":"Ruth 2:8"},"en":{"text":"Boaz tells Ruth to stay in his field","ref":"Ruth 2:8"},"es":{"text":"Booz pide a Ruth que se quede en su campo","ref":"Rut 2:8"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Boaz compra tudo diante dos anciãos","ref":"Rute 4:9"},"fr":{"text":"Boaz acquiert tout devant les anciens","ref":"Ruth 4:9"},"en":{"text":"Boaz buys all before the elders","ref":"Ruth 4:9"},"es":{"text":"Booz toma todo delante de los ancianos","ref":"Rut 4:9"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-019","type":"verse","level":"medium","testament":"ot","book":"RUT","chapter":2,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"E eis que Boaz veio de Belém, e disse aos _____: O SENHOR seja convosco. E eles responderam: O SENHOR te abençoe.","bible_ref":"Rute 2:4","verse_text":"E eis que Boaz veio de Belém, e disse aos ceifeiros: O SENHOR seja convosco. E eles responderam: O SENHOR te abençoe."},"fr":{"prompt":"Et voici, Boaz vint de Bethléhem, et il dit aux _____: Que l’Éternel soit avec vous! Ils lui répondirent: Que l’Éternel te bénisse!","bible_ref":"Ruth 2:4","verse_text":"Et voici, Boaz vint de Bethléhem, et il dit aux moissonneurs: Que l’Éternel soit avec vous! Ils lui répondirent: Que l’Éternel te bénisse!"},"en":{"prompt":"And, behold, Boaz came from Beth-lehem, and said unto the _____, The LORD be with you. And they answered him, The LORD bless thee.","bible_ref":"Ruth 2:4","verse_text":"And, behold, Boaz came from Beth-lehem, and said unto the reapers, The LORD be with you. And they answered him, The LORD bless thee."},"es":{"prompt":"Y he aquí que Booz vino de Beth-lehem, y dijo á los _____: Jehová sea con vosotros. Y ellos respondieron: Jehová te bendiga.","bible_ref":"Rut 2:4","verse_text":"Y he aquí que Booz vino de Beth-lehem, y dijo á los segadores: Jehová sea con vosotros. Y ellos respondieron: Jehová te bendiga."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"servos"},"fr":{"text":"serviteurs"},"en":{"text":"servants"},"es":{"text":"siervos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"soldados"},"fr":{"text":"soldats"},"en":{"text":"soldiers"},"es":{"text":"soldados"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"pastores"},"fr":{"text":"bergers"},"en":{"text":"shepherds"},"es":{"text":"pastores"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"ceifeiros"},"fr":{"text":"moissonneurs"},"en":{"text":"reapers"},"es":{"text":"segadores"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-020","type":"choice","level":"medium","testament":"ot","book":"1SA","chapter":8,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Quando Samuel envelheceu, o que lhe pediram os anciãos de Israel?","bible_ref":"1 Samuel 8:5","verse_text":"E disseram-lhe: Eis que tu envelheceste, e teus filhos não vão por teus caminhos: portanto, constitui-nos agora um rei que nos julgue, como todas as nações."},"fr":{"prompt":"Quand Samuel fut devenu vieux, que lui demandèrent les anciens d’Israël ?","bible_ref":"1 Samuel 8:5","verse_text":"Ils lui dirent: Voici, tu es vieux, et tes fils ne marchent point sur tes traces; maintenant, établis sur nous un roi pour nous juger, comme il y en a chez toutes les nations."},"en":{"prompt":"When Samuel was old, what did the elders of Israel ask him for?","bible_ref":"1 Samuel 8:5","verse_text":"And said unto him, Behold, thou art old, and thy sons walk not in thy ways: now make us a king to judge us like all the nations."},"es":{"prompt":"Cuando Samuel envejeció, ¿qué le pidieron los ancianos de Israel?","bible_ref":"1 Samuel 8:5","verse_text":"Y dijéronle: He aquí tú has envejecido, y tus hijos no van por tus caminos: por tanto, constitúyenos ahora un rey que nos juzgue, como todas las gentes."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um rei que os julgasse"},"fr":{"text":"Un roi pour les juger"},"en":{"text":"A king to judge them"},"es":{"text":"Un rey que los juzgase"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um templo novo"},"fr":{"text":"Un nouveau temple"},"en":{"text":"A new temple"},"es":{"text":"Un templo nuevo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Mais terras para as tribos"},"fr":{"text":"Plus de terres pour les tribus"},"en":{"text":"More land for the tribes"},"es":{"text":"Más tierras para las tribus"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-021","type":"choice","level":"medium","testament":"ot","book":"1SA","chapter":9,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Que animais do pai de Saul se tinham perdido?","bible_ref":"1 Samuel 9:3","verse_text":"E haviam-se perdido as asnas de Quis, pai de Saul; pelo que disse Quis a Saul seu filho: Toma agora contigo algum dos criados, e levanta-te, e vai a buscar as asnas."},"fr":{"prompt":"Quels animaux du père de Saül s’étaient égarés ?","bible_ref":"1 Samuel 9:3","verse_text":"Les ânesses de Kis, père de Saül, s’égarèrent; et Kis dit à Saül, son fils: Prends avec toi l’un des serviteurs, lève-toi, va, et cherche les ânesses."},"en":{"prompt":"Which animals of Saul’s father were lost?","bible_ref":"1 Samuel 9:3","verse_text":"And the asses of Kish Saul’s father were lost. And Kish said to Saul his son, Take now one of the servants with thee, and arise, go seek the asses."},"es":{"prompt":"¿Qué animales del padre de Saúl se habían perdido?","bible_ref":"1 Samuel 9:3","verse_text":"Y habíanse perdido las asnas de Cis, padre de Saúl; por lo que dijo Cis á Saúl su hijo: Toma ahora contigo alguno de los criados, y levántate, y ve á buscar las asnas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"As asnas"},"fr":{"text":"Les ânesses"},"en":{"text":"The asses"},"es":{"text":"Las asnas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"As ovelhas"},"fr":{"text":"Les brebis"},"en":{"text":"The sheep"},"es":{"text":"Las ovejas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Os camelos"},"fr":{"text":"Les chameaux"},"en":{"text":"The camels"},"es":{"text":"Los camellos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-022","type":"choice","level":"medium","testament":"ot","book":"1SA","chapter":2,"verse_start":19,"verse_end":19,"texts":{"pt":{"prompt":"O que fazia a mãe de Samuel para ele todos os anos?","bible_ref":"1 Samuel 2:19","verse_text":"E fazia-lhe sua mãe uma túnica pequena, e a trazia a ele a cada ano, quando subia com seu marido a oferecer o sacrifício costumeiro."},"fr":{"prompt":"Que faisait chaque année la mère de Samuel pour lui ?","bible_ref":"1 Samuel 2:19","verse_text":"Sa mère lui faisait chaque année une petite robe, et la lui apportait en montant avec son mari pour offrir le sacrifice annuel."},"en":{"prompt":"What did Samuel’s mother make for him every year?","bible_ref":"1 Samuel 2:19","verse_text":"Moreover his mother made him a little coat, and brought it to him from year to year, when she came up with her husband to offer the yearly sacrifice."},"es":{"prompt":"¿Qué le hacía cada año a Samuel su madre?","bible_ref":"1 Samuel 2:19","verse_text":"Y hacíale su madre una túnica pequeña, y traíasela cada año, cuando subía con su marido á ofrecer el sacrificio acostumbrado."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma túnica pequena"},"fr":{"text":"Une petite robe"},"en":{"text":"A little coat"},"es":{"text":"Una túnica pequeña"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um par de sandálias"},"fr":{"text":"Une paire de sandales"},"en":{"text":"A pair of sandals"},"es":{"text":"Un par de sandalias"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um bolo de mel"},"fr":{"text":"Un gâteau au miel"},"en":{"text":"A honey cake"},"es":{"text":"Una torta de miel"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-023","type":"choice","level":"medium","testament":"ot","book":"1SA","chapter":25,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Como se chamava a mulher sensata e bela de Nabal?","bible_ref":"1 Samuel 25:3","verse_text":"O nome daquele homem era Nabal, e o nome de sua mulher, Abigail. E era aquela mulher de bom entendimento e de boa aparência; mas o homem era duro e de maus feitos; e era da linhagem de Calebe."},"fr":{"prompt":"Comment s’appelait la femme sensée et belle de Nabal ?","bible_ref":"1 Samuel 25:3","verse_text":"Le nom de cet homme était Nabal, et sa femme s’appelait Abigaïl; c’était une femme de bon sens et belle de figure, mais l’homme était dur et méchant dans ses actions. Il descendait de Caleb."},"en":{"prompt":"What was the name of Nabal’s wife, a woman of good understanding?","bible_ref":"1 Samuel 25:3","verse_text":"Now the name of the man was Nabal; and the name of his wife Abigail: and she was a woman of good understanding, and of a beautiful countenance: but the man was churlish and evil in his doings; and he was of the house of Caleb."},"es":{"prompt":"¿Cómo se llamaba la mujer de buen entendimiento de Nabal?","bible_ref":"1 Samuel 25:3","verse_text":"El nombre de aquel varón era Nabal, y el nombre de su mujer, Abigail. Y era aquella mujer de buen entendimiento y de buena gracia; mas el hombre era duro y de malos hechos; y era del linaje de Caleb."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Abigail"},"fr":{"text":"Abigaïl"},"en":{"text":"Abigail"},"es":{"text":"Abigail"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Mical"},"fr":{"text":"Mical"},"en":{"text":"Michal"},"es":{"text":"Michâl"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Penina"},"fr":{"text":"Peninna"},"en":{"text":"Peninnah"},"es":{"text":"Peninna"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-024","type":"choice","level":"medium","testament":"ot","book":"1SA","chapter":1,"verse_start":28,"verse_end":28,"texts":{"pt":{"prompt":"Que disse Ana que fazia com o seu filho Samuel?","bible_ref":"1 Samuel 1:28","verse_text":"Eu, pois, o devolvo também ao SENHOR: todos os dias que viver, será do SENHOR. E adorou ali ao SENHOR."},"fr":{"prompt":"Que dit Anne au sujet de son fils Samuel ?","bible_ref":"1 Samuel 1:28","verse_text":"Aussi je veux le prêter à l’Éternel: il sera toute sa vie prêté à l’Éternel. Et ils se prosternèrent là devant l’Éternel"},"en":{"prompt":"What did Hannah say she did with her son Samuel?","bible_ref":"1 Samuel 1:28","verse_text":"Therefore also I have lent him to the LORD; as long as he liveth he shall be lent to the LORD. And he worshipped the LORD there."},"es":{"prompt":"¿Qué dijo Anna que hacía con su hijo Samuel?","bible_ref":"1 Samuel 1:28","verse_text":"Yo pues le vuelvo también á Jehová: todos los días que viviere, será de Jehová. Y adoró allí á Jehová."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Que o devolvia ao SENHOR por toda a vida"},"fr":{"text":"Qu’elle le prêtait à l’Éternel pour toute sa vie"},"en":{"text":"That she lent him to the LORD as long as he lived"},"es":{"text":"Que lo volvía a Jehová por toda su vida"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Que o deixava em casa com o pai"},"fr":{"text":"Qu’elle le gardait à la maison avec son père"},"en":{"text":"That she kept him at home with his father"},"es":{"text":"Que lo dejaba en casa con su padre"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Que o mandava servir o rei"},"fr":{"text":"Qu’elle l’envoyait servir le roi"},"en":{"text":"That she sent him to serve the king"},"es":{"text":"Que lo enviaba a servir al rey"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-025","type":"order","level":"medium","testament":"ot","book":"1SA","chapter":18,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"1 Samuel 18:11","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"1 Samuel 18:11","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"1 Samuel 18:11","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"1 Samuel 18:11","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Saul atira a lança contra David","ref":"1 Samuel 18:11"},"fr":{"text":"Saül lance sa lance contre David","ref":"1 Samuel 18:11"},"en":{"text":"Saul casts the javelin at David","ref":"1 Samuel 18:11"},"es":{"text":"Saúl arroja la lanza contra David","ref":"1 Samuel 18:11"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Mical faz descer David pela janela","ref":"1 Samuel 19:12"},"fr":{"text":"Mical fait descendre David par la fenêtre","ref":"1 Samuel 19:12"},"en":{"text":"Michal lets David down through a window","ref":"1 Samuel 19:12"},"es":{"text":"Michâl descuelga a David por una ventana","ref":"1 Samuel 19:12"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jónatas atira flechas para avisar David","ref":"1 Samuel 20:36"},"fr":{"text":"Jonathan tire des flèches pour avertir David","ref":"1 Samuel 20:36"},"en":{"text":"Jonathan shoots arrows to warn David","ref":"1 Samuel 20:36"},"es":{"text":"Jonathán tira saetas para avisar a David","ref":"1 Samuel 20:36"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"David foge para a cova de Adulão","ref":"1 Samuel 22:1"},"fr":{"text":"David se sauve dans la caverne d’Adullam","ref":"1 Samuel 22:1"},"en":{"text":"David escapes to the cave Adullam","ref":"1 Samuel 22:1"},"es":{"text":"David huye a la cu