select public.upsert_bank_question($json${"id":"hist2-medium-026","type":"verse","level":"medium","testament":"ot","book":"1SA","chapter":17,"verse_start":45,"verse_end":45,"texts":{"pt":{"prompt":"Então disse Davi ao filisteu: Tu vens a mim com espada e lança e escudo; mas eu venho a ti no _____ do SENHOR dos exércitos, o Deus dos esquadrões de Israel, que tu provocaste.","bible_ref":"1 Samuel 17:45","verse_text":"Então disse Davi ao filisteu: Tu vens a mim com espada e lança e escudo; mas eu venho a ti no nome do SENHOR dos exércitos, o Deus dos esquadrões de Israel, que tu provocaste."},"fr":{"prompt":"David dit au Philistin: Tu marches contre moi avec l’épée, la lance et le javelot; et moi, je marche contre toi au _____ de l’Éternel des armées, du Dieu de l’armée d’Israël, que tu as insultée.","bible_ref":"1 Samuel 17:45","verse_text":"David dit au Philistin: Tu marches contre moi avec l’épée, la lance et le javelot; et moi, je marche contre toi au nom de l’Éternel des armées, du Dieu de l’armée d’Israël, que tu as insultée."},"en":{"prompt":"Then said David to the Philistine, Thou comest to me with a sword, and with a spear, and with a shield: but I come to thee in the _____ of the LORD of hosts, the God of the armies of Israel, whom thou hast defied.","bible_ref":"1 Samuel 17:45","verse_text":"Then said David to the Philistine, Thou comest to me with a sword, and with a spear, and with a shield: but I come to thee in the name of the LORD of hosts, the God of the armies of Israel, whom thou hast defied."},"es":{"prompt":"Entonces dijo David al Filisteo: Tú vienes á mí con espada y lanza y escudo; mas yo vengo á ti en el _____ de Jehová de los ejércitos, el Dios de los escuadrones de Israel, que tú has provocado.","bible_ref":"1 Samuel 17:45","verse_text":"Entonces dijo David al Filisteo: Tú vienes á mí con espada y lanza y escudo; mas yo vengo á ti en el nombre de Jehová de los ejércitos, el Dios de los escuadrones de Israel, que tú has provocado."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"braço"},"fr":{"text":"bras"},"en":{"text":"arm"},"es":{"text":"brazo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"socorro"},"fr":{"text":"secours"},"en":{"text":"help"},"es":{"text":"socorro"}}},{"position":3,"is_correct":true,"texts":{"pt":{"text":"nome"},"fr":{"text":"nom"},"en":{"text":"name"},"es":{"text":"nombre"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"poder"},"fr":{"text":"pouvoir"},"en":{"text":"power"},"es":{"text":"poder"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-027","type":"verse","level":"medium","testament":"ot","book":"1SA","chapter":2,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Ele levanta do _____ ao pobre, e ao necessitado ergue do esterco, para assentá-lo com os príncipes; e faz que tenham por propriedade assento de honra; porque do SENHOR são os alicerces da terra, e assentou o mundo sobre eles.","bible_ref":"1 Samuel 2:8","verse_text":"Ele levanta do pó ao pobre, e ao necessitado ergue do esterco, para assentá-lo com os príncipes; e faz que tenham por propriedade assento de honra; porque do SENHOR são os alicerces da terra, e assentou o mundo sobre eles."},"fr":{"prompt":"De la _____ il retire le pauvre, Du fumier il relève l’indigent, Pour les faire asseoir avec les grands. Et il leur donne en partage un trône de gloire; Car à l’Éternel sont les colonnes de la terre, Et c’est sur elles qu’il a posé le monde.","bible_ref":"1 Samuel 2:8","verse_text":"De la poussière il retire le pauvre, Du fumier il relève l’indigent, Pour les faire asseoir avec les grands. Et il leur donne en partage un trône de gloire; Car à l’Éternel sont les colonnes de la terre, Et c’est sur elles qu’il a posé le monde."},"en":{"prompt":"He raiseth up the poor out of the _____, and lifteth up the beggar from the dunghill, to set them among princes, and to make them inherit the throne of glory: for the pillars of the earth are the LORD’s, and he hath set the world upon them.","bible_ref":"1 Samuel 2:8","verse_text":"He raiseth up the poor out of the dust, and lifteth up the beggar from the dunghill, to set them among princes, and to make them inherit the throne of glory: for the pillars of the earth are the LORD’s, and he hath set the world upon them."},"es":{"prompt":"El levanta del _____ al pobre, y al menesteroso ensalza del estiércol, para asentarlo con los príncipes; y hace que tengan por heredad asiento de honra: porque de Jehová son las columnas de la tierra, y él asentó sobre ellas el mundo.","bible_ref":"1 Samuel 2:8","verse_text":"El levanta del polvo al pobre, y al menesteroso ensalza del estiércol, para asentarlo con los príncipes; y hace que tengan por heredad asiento de honra: porque de Jehová son las columnas de la tierra, y él asentó sobre ellas el mundo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"pó"},"fr":{"text":"poussière"},"en":{"text":"dust"},"es":{"text":"polvo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"monte"},"fr":{"text":"montagne"},"en":{"text":"mountain"},"es":{"text":"monte"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"mar"},"fr":{"text":"mer"},"en":{"text":"sea"},"es":{"text":"mar"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"fogo"},"fr":{"text":"flamme"},"en":{"text":"fire"},"es":{"text":"fuego"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-028","type":"choice","level":"medium","testament":"ot","book":"2SA","chapter":5,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Que idade tinha David quando começou a reinar?","bible_ref":"2 Samuel 5:4","verse_text":"Era Davi de trinta anos quando começou a reinar, e reinou quarenta anos."},"fr":{"prompt":"Quel âge avait David lorsqu’il devint roi ?","bible_ref":"2 Samuel 5:4","verse_text":"David était âgé de trente ans lorsqu’il devint roi, et il régna quarante ans."},"en":{"prompt":"How old was David when he began to reign?","bible_ref":"2 Samuel 5:4","verse_text":"David was thirty years old when he began to reign, and he reigned forty years."},"es":{"prompt":"¿Qué edad tenía David cuando comenzó a reinar?","bible_ref":"2 Samuel 5:4","verse_text":"Era David de treinta años cuando comenzó á reinar, y reinó cuarenta años."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Trinta anos"},"fr":{"text":"Trente ans"},"en":{"text":"Thirty years"},"es":{"text":"Treinta años"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Quarenta anos"},"fr":{"text":"Quarante ans"},"en":{"text":"Forty years"},"es":{"text":"Cuarenta años"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Vinte anos"},"fr":{"text":"Vingt ans"},"en":{"text":"Twenty years"},"es":{"text":"Veinte años"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-029","type":"choice","level":"medium","testament":"ot","book":"2SA","chapter":6,"verse_start":6,"verse_end":7,"texts":{"pt":{"prompt":"Quem morreu por ter estendido a mão para segurar a arca de Deus?","bible_ref":"2 Samuel 6:6-7","verse_text":"E quando chegaram à eira de Nacom, Uzá estendeu a mão à arca de Deus, e segurou-a; porque os bois a sacudiam. E o furor do SENHOR se acendeu contra Uzá, e feriu-o ali Deus por aquela imprudência, e caiu ali morto junto à arca de Deus."},"fr":{"prompt":"Qui mourut pour avoir étendu la main vers l’arche de Dieu ?","bible_ref":"2 Samuel 6:6-7","verse_text":"Lorsqu’ils furent arrivés à l’aire de Nacon, Uzza étendit la main vers l’arche de Dieu et la saisit, parce que les bœufs la faisaient pencher. La colère de l’Éternel s’enflamma contre Uzza, et Dieu le frappa sur place à cause de sa faute. Uzza mourut là, près de l’arche de Dieu."},"en":{"prompt":"Who died after he put forth his hand to the ark of God?","bible_ref":"2 Samuel 6:6-7","verse_text":"And when they came to Nachon’s threshingfloor, Uzzah put forth his hand to the ark of God, and took hold of it; for the oxen shook it. And the anger of the LORD was kindled against Uzzah; and God smote him there for his error; and there he died by the ark of God."},"es":{"prompt":"¿Quién murió por extender la mano al arca de Dios?","bible_ref":"2 Samuel 6:6-7","verse_text":"Y cuando llegaron á la era de Nachôn, Uzza extendió la mano al arca de Dios, y túvola; porque los bueyes daban sacudidas. Y el furor de Jehová se encendió contra Uzza, é hiriólo allí Dios por aquella temeridad, y cayó allí muerto junto al arca de Dios."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uzá"},"fr":{"text":"Uzza"},"en":{"text":"Uzzah"},"es":{"text":"Uzza"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Aiô"},"fr":{"text":"Achjo"},"en":{"text":"Ahio"},"es":{"text":"Ahio"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Obede-Edom"},"fr":{"text":"Obed-Édom"},"en":{"text":"Obed-edom"},"es":{"text":"Obed-edom"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-030","type":"choice","level":"medium","testament":"ot","book":"2SA","chapter":12,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Na história de Natã, o que tinha o homem pobre?","bible_ref":"2 Samuel 12:3","verse_text":"Mas o pobre não tinha mais que uma só cordeira, que ele havia comprado e criado, e que havia crescido com ele e com seus filhos juntamente, comendo de seu bocado, e bebendo de seu vaso, e dormindo em seu fundo: e tinha-a como de uma vez filha."},"fr":{"prompt":"Dans l’histoire de Nathan, que possédait le pauvre ?","bible_ref":"2 Samuel 12:3","verse_text":"Le pauvre n’avait rien du tout qu’une petite brebis, qu’il avait achetée; il la nourrissait, et elle grandissait chez lui avec ses enfants; elle mangeait de son pain, buvait dans sa coupe, dormait sur son sein, et il la regardait comme sa fille."},"en":{"prompt":"In Nathan’s story, what did the poor man have?","bible_ref":"2 Samuel 12:3","verse_text":"But the poor man had nothing, save one little ewe lamb, which he had bought and nourished up: and it grew up together with him, and with his children; it did eat of his own meat, and drank of his own cup, and lay in his bosom, and was unto him as a daughter."},"es":{"prompt":"En la historia de Nathán, ¿qué tenía el hombre pobre?","bible_ref":"2 Samuel 12:3","verse_text":"Mas el pobre no tenía más que una sola cordera, que él había comprado y criado, y que había crecido con él y con sus hijos juntamente, comiendo de su bocado, y bebiendo de su vaso, y durmiendo en su seno: y teníala como á una hija."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma só cordeira"},"fr":{"text":"Une seule petite brebis"},"en":{"text":"One little ewe lamb"},"es":{"text":"Una sola cordera"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um jumento velho"},"fr":{"text":"Un vieil âne"},"en":{"text":"An old ass"},"es":{"text":"Un asno viejo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma pequena vinha"},"fr":{"text":"Une petite vigne"},"en":{"text":"A small vineyard"},"es":{"text":"Una pequeña viña"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-031","type":"choice","level":"medium","testament":"ot","book":"2SA","chapter":23,"verse_start":15,"verse_end":15,"texts":{"pt":{"prompt":"David desejou beber água da cisterna de que cidade?","bible_ref":"2 Samuel 23:15","verse_text":"E Davi teve desejo, e disse: Quem me dera a beber da água da cisterna de Belém, que está à porta!"},"fr":{"prompt":"David désira boire de l’eau de la citerne de quelle ville ?","bible_ref":"2 Samuel 23:15","verse_text":"David eut un désir, et il dit: Qui me fera boire de l’eau de la citerne qui est à la porte de Bethléhem?"},"en":{"prompt":"David longed to drink water from the well of which town?","bible_ref":"2 Samuel 23:15","verse_text":"And David longed, and said, Oh that one would give me drink of the water of the well of Beth-lehem, which is by the gate!"},"es":{"prompt":"¿De la cisterna de qué ciudad deseó David beber agua?","bible_ref":"2 Samuel 23:15","verse_text":"Y David tuvo deseo, y dijo: ¡Quién me diera á beber del agua de la cisterna de Beth-lehem, que está á la puerta!"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Belém"},"fr":{"text":"Bethléhem"},"en":{"text":"Beth-lehem"},"es":{"text":"Beth-lehem"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Hebrom"},"fr":{"text":"Hébron"},"en":{"text":"Hebron"},"es":{"text":"Hebrón"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jericó"},"fr":{"text":"Jéricho"},"en":{"text":"Jericho"},"es":{"text":"Jericó"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-medium-032","type":"choice","level":"medium","testament":"ot","book":"2SA","chapter":6,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Quem viu David a saltar diante do SENHOR e o desprezou no seu coração?","bible_ref":"2 Samuel 6:16","verse_text":"E quando a arca do SENHOR chegou à cidade de Davi, aconteceu que Mical filha de Saul olhou desde uma janela, e viu ao rei Davi que saltava com toda sua força diante do SENHOR: e menosprezou-lhe em seu coração."},"fr":{"prompt":"Qui vit David sauter devant l’Éternel et le méprisa dans son cœur ?","bible_ref":"2 Samuel 6:16","verse_text":"Comme l’arche de l’Éternel entrait dans la cité de David, Mical, fille de Saül, regardait par la fenêtre, et, voyant le roi David sauter et danser devant l’Éternel, elle le méprisa dans son cœur."},"en":{"prompt":"Who saw David leaping before the LORD and despised him in her heart?","bible_ref":"2 Samuel 6:16","verse_text":"And as the ark of the LORD came into the city of David, Michal Saul’s daughter looked through a window, and saw king David leaping and dancing before the LORD; and she despised him in her heart."},"es":{"prompt":"¿Quién vio a David saltar delante de Jehová y lo menospreció en su corazón?","bible_ref":"2 Samuel 6:16","verse_text":"Y como el arca de Jehová llegó á la ciudad de David, aconteció que Michâl hija de Saúl miró desde una ventana, y vió al rey David que saltaba con toda su fuerza delante de Jehová: y menosprecióle en su corazón."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Mical, filha de Saul"},"fr":{"text":"Mical, fille de Saül"},"en":{"text":"Michal, Saul’s daughter"},"es":{"text":"Michâl, hija de Saúl"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Bate-Seba"},"fr":{"text":"Bath-Schéba"},"en":{"text":"Bath-sheba"},"es":{"text":"Bath-sheba"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Abigail"},"fr":{"text":"Abigaïl"},"en":{"text":"Abigail"},"es":{"text":"Abigail"}}}]}$json$::jsonb);
