select public.upsert_bank_question($json${"id":"hist2-hard-001","type":"choice","level":"hard","testament":"ot","book":"JOS","chapter":14,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Segundo Josué 14:10, que idade tinha Calebe quando pediu a sua herança a Josué?","bible_ref":"Josué 14:10","verse_text":"Agora bem, o SENHOR me fez viver, como ele disse, estes quarenta e cinco anos, desde o tempo que o SENHOR falou estas palavras a Moisés, quando Israel andava pelo deserto: e agora, eis que sou hoje dia de oitenta e cinco anos:"},"fr":{"prompt":"Selon Josué 14:10, quel âge avait Caleb quand il demanda son héritage à Josué ?","bible_ref":"Josué 14:10","verse_text":"Maintenant voici, l’Éternel m’a fait vivre, comme il l’a dit. Il y a quarante-cinq ans que l’Éternel parlait ainsi à Moïse, lorsqu’Israël marchait dans le désert; et maintenant voici, je suis âgé aujourd’hui de quatre-vingt-cinq ans."},"en":{"prompt":"According to Joshua 14:10, how old was Caleb when he asked Joshua for his inheritance?","bible_ref":"Joshua 14:10","verse_text":"And now, behold, the LORD hath kept me alive, as he said, these forty and five years, even since the LORD spake this word unto Moses, while the children of Israel wandered in the wilderness: and now, lo, I am this day fourscore and five years old."},"es":{"prompt":"Según Josué 14:10, ¿qué edad tenía Caleb cuando pidió su heredad a Josué?","bible_ref":"Josué 14:10","verse_text":"Ahora bien, Jehová me ha hecho vivir, como él dijo, estos cuarenta y cinco años, desde el tiempo que Jehová habló estas palabras á Moisés, cuando Israel andaba por el desierto: y ahora, he aquí, soy hoy día de ochenta y cinco años:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Oitenta e cinco anos"},"fr":{"text":"Quatre-vingt-cinq ans"},"en":{"text":"Eighty-five years"},"es":{"text":"Ochenta y cinco años"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Quarenta anos"},"fr":{"text":"Quarante ans"},"en":{"text":"Forty years"},"es":{"text":"Cuarenta años"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Cento e dez anos"},"fr":{"text":"Cent dix ans"},"en":{"text":"A hundred and ten years"},"es":{"text":"Ciento diez años"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-002","type":"choice","level":"hard","testament":"ot","book":"JOS","chapter":7,"verse_start":26,"verse_end":26,"texts":{"pt":{"prompt":"Que nome recebeu o lugar onde se levantou um monte de pedras sobre Acã?","bible_ref":"Josué 7:26","verse_text":"E levantaram sobre ele um grande amontoado de pedras, até hoje. E o SENHOR se apaziguou da ira de seu furor. E por isto foi chamado aquele lugar o Vale de Acor, até hoje."},"fr":{"prompt":"Quel nom reçut le lieu où l’on éleva un monceau de pierres sur Acan ?","bible_ref":"Josué 7:26","verse_text":"et l’on éleva sur Acan un grand monceau de pierres, qui subsiste encore aujourd’hui. Et l’Éternel revint de l’ardeur de sa colère. C’est à cause de cet événement qu’on a donné jusqu’à ce jour à ce lieu le nom de vallée d’Acor."},"en":{"prompt":"What was the place called where a heap of stones was raised over Achan?","bible_ref":"Joshua 7:26","verse_text":"And they raised over him a great heap of stones unto this day. So the LORD turned from the fierceness of his anger. Wherefore the name of that place was called, The valley of Achor, unto this day."},"es":{"prompt":"¿Qué nombre recibió el lugar donde levantaron un montón de piedras sobre Achân?","bible_ref":"Josué 7:26","verse_text":"Y levantaron sobre él un gran montón de piedras, hasta hoy. Y Jehová se tornó de la ira de su furor. Y por esto fué llamado aquel lugar el Valle de Achôr, hasta hoy."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Vale de Acor"},"fr":{"text":"Vallée d’Acor"},"en":{"text":"The valley of Achor"},"es":{"text":"Valle de Achôr"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Vale de Aijalom"},"fr":{"text":"Vallée d’Ajalon"},"en":{"text":"The valley of Ajalon"},"es":{"text":"Valle de Ajalón"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Vale de Soreque"},"fr":{"text":"Vallée de Sorek"},"en":{"text":"The valley of Sorek"},"es":{"text":"Valle de Sorec"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-003","type":"choice","level":"hard","testament":"ot","book":"JOS","chapter":24,"verse_start":32,"verse_end":32,"texts":{"pt":{"prompt":"Onde foram enterrados os ossos de José trazidos do Egito?","bible_ref":"Josué 24:32","verse_text":"E enterraram em Siquém os ossos de José que os filhos de Israel haviam trazido do Egito, na parte do campo que Jacó comprou dos filhos de Hamor, pai de Siquém, por cem peças de prata; e foi em possessão aos filhos de José."},"fr":{"prompt":"Où furent enterrés les os de Joseph rapportés d’Égypte ?","bible_ref":"Josué 24:32","verse_text":"Les os de Joseph, que les enfants d’Israël avaient rapportés d’Égypte, furent enterrés à Sichem, dans la portion du champ que Jacob avait achetée des fils de Hamor, père de Sichem, pour cent kesita, et qui appartint à l’héritage des fils de Joseph."},"en":{"prompt":"Where were the bones of Joseph, brought up out of Egypt, buried?","bible_ref":"Joshua 24:32","verse_text":"And the bones of Joseph, which the children of Israel brought up out of Egypt, buried they in Shechem, in a parcel of ground which Jacob bought of the sons of Hamor the father of Shechem for an hundred pieces of silver: and it became the inheritance of the children of Joseph."},"es":{"prompt":"¿Dónde enterraron los huesos de José traídos de Egipto?","bible_ref":"Josué 24:32","verse_text":"Y enterraron en Sichêm los huesos de José que los hijos de Israel habían traído de Egipto, en la parte del campo que Jacob compró de los hijos de Hemor padre de Sichêm, por cien corderas; y fué en posesión á los hijos de José."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Em Siquém"},"fr":{"text":"À Sichem"},"en":{"text":"In Shechem"},"es":{"text":"En Sichêm"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Em Hebrom"},"fr":{"text":"À Hébron"},"en":{"text":"In Hebron"},"es":{"text":"En Hebrón"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Em Siló"},