select public.upsert_bank_question($json${"id":"hist2-hard-004","type":"choice","level":"hard","testament":"ot","book":"JOS","chapter":3,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Junto de que cidade se amontoaram as águas do Jordão quando Israel passou?","bible_ref":"Josué 3:16","verse_text":"As águas que vinham de cima pararam, e amontoaram-se bem longe, na cidade de Adã, que está ao lado de Zaretã; e as que desciam ao mar das planícies, ao mar Salgado, esgotaram-se e foram totalmente interrompidas; e o povo passou em frente de Jericó."},"fr":{"prompt":"Près de quelle ville les eaux du Jourdain s’élevèrent-elles en un monceau quand Israël passa ?","bible_ref":"Josué 3:16","verse_text":"les eaux qui descendent d’en haut s’arrêtèrent, et s’élevèrent en un monceau, à une très grande distance, près de la ville d’Adam, qui est à côté de Tsarthan; et celles qui descendaient vers la mer de la plaine, la mer Salée, furent complètement coupées. Le peuple passa vis-à-vis de Jéricho."},"en":{"prompt":"Near which city did the waters of Jordan rise up upon an heap when Israel passed over?","bible_ref":"Joshua 3:16","verse_text":"That the waters which came down from above stood and rose up upon an heap very far from the city Adam, that is beside Zaretan: and those that came down toward the sea of the plain, even the salt sea, failed, and were cut off: and the people passed over right against Jericho."},"es":{"prompt":"¿Junto a qué ciudad se amontonaron las aguas del Jordán cuando pasó Israel?","bible_ref":"Josué 3:16","verse_text":"Las aguas que venían de arriba, se pararon como en un montón bien lejos de la ciudad de Adam, que está al lado de Sarethan; y las que descendían á la mar de los llanos, al mar Salado, se acabaron y fueron partidas; y el pueblo pasó en derecho de Jericó."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Adã"},"fr":{"text":"Adam"},"en":{"text":"Adam"},"es":{"text":"Adam"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Gilgal"},"fr":{"text":"Guilgal"},"en":{"text":"Gilgal"},"es":{"text":"Gilgal"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Ai"},"fr":{"text":"Aï"},"en":{"text":"Ai"},"es":{"text":"Hai"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-005","type":"order","level":"hard","testament":"ot","book":"JOS","chapter":14,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"Josué 14:13","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"Josué 14:13","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"Joshua 14:13","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"Josué 14:13","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Josué dá Hebrom a Calebe","ref":"Josué 14:13"},"fr":{"text":"Josué donne Hébron à Caleb","ref":"Josué 14:13"},"en":{"text":"Joshua gives Hebron to Caleb","ref":"Joshua 14:13"},"es":{"text":"Josué da Hebrón a Caleb","ref":"Josué 14:13"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Israel monta o tabernáculo em Siló","ref":"Josué 18:1"},"fr":{"text":"Israël dresse la tente d’assignation à Silo","ref":"Josué 18:1"},"en":{"text":"Israel sets up the tabernacle at Shiloh","ref":"Joshua 18:1"},"es":{"text":"Israel asienta el tabernáculo en Silo","ref":"Josué 18:1"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Deus manda escolher as cidades de refúgio","ref":"Josué 20:2"},"fr":{"text":"Dieu fait établir les villes de refuge","ref":"Josué 20:2"},"en":{"text":"God orders the cities of refuge","ref":"Joshua 20:2"},"es":{"text":"Dios manda señalar las ciudades de refugio","ref":"Josué 20:2"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Josué ergue uma grande pedra junto ao santuário","ref":"Josué 24:26"},"fr":{"text":"Josué dresse une grande pierre près du sanctuaire","ref":"Josué 24:26"},"en":{"text":"Joshua sets up a great stone by the sanctuary","ref":"Joshua 24:26"},"es":{"text":"Josué levanta una gran piedra junto al santuario","ref":"Josué 24:26"}}}]}$js