select public.upsert_bank_question($json${"id":"hist2-hard-006","type":"verse","level":"hard","testament":"ot","book":"JOS","chapter":24,"verse_start":24,"verse_end":24,"texts":{"pt":{"prompt":"E o povo respondeu a Josué: Ao SENHOR nosso Deus serviremos, e à sua _____ obedeceremos.","bible_ref":"Josué 24:24","verse_text":"E o povo respondeu a Josué: Ao SENHOR nosso Deus serviremos, e à sua voz obedeceremos."},"fr":{"prompt":"Et le peuple dit à Josué: Nous servirons l’Éternel, notre Dieu, et nous obéirons à sa _____.","bible_ref":"Josué 24:24","verse_text":"Et le peuple dit à Josué: Nous servirons l’Éternel, notre Dieu, et nous obéirons à sa voix."},"en":{"prompt":"And the people said unto Joshua, The LORD our God will we serve, and his _____ will we obey.","bible_ref":"Joshua 24:24","verse_text":"And the people said unto Joshua, The LORD our God will we serve, and his voice will we obey."},"es":{"prompt":"Y el pueblo respondió á Josué: A Jehová nuestro Dios serviremos, y á su _____ obedeceremos.","bible_ref":"Josué 24:24","verse_text":"Y el pueblo respondió á Josué: A Jehová nuestro Dios serviremos, y á su voz obedeceremos."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"palavra"},"fr":{"text":"parole"},"en":{"text":"word"},"es":{"text":"palabra"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"mão"},"fr":{"text":"main"},"en":{"text":"hand"},"es":{"text":"mano"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"lei"},"fr":{"text":"loi"},"en":{"text":"law"},"es":{"text":"ley"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"voz"},"fr":{"text":"voix"},"en":{"text":"voice"},"es":{"text":"voz"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-007","type":"choice","level":"hard","testament":"ot","book":"JDG","chapter":3,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Que libertador, irmão mais novo de Calebe, levantou o SENHOR para Israel?","bible_ref":"Juízes 3:9","verse_text":"E clamaram os filhos de Israel ao SENHOR; e o SENHOR suscitou salvador aos filhos de Israel e livrou-os; é, a saber, a Otniel filho de Quenaz, irmão menor de Calebe."},"fr":{"prompt":"Quel libérateur, frère cadet de Caleb, l’Éternel suscita-t-il à Israël ?","bible_ref":"Juges 3:9","verse_text":"Les enfants d’Israël crièrent à l’Éternel, et l’Éternel leur suscita un libérateur qui les délivra, Othniel, fils de Kenaz, frère cadet de Caleb."},"en":{"prompt":"Which deliverer, Caleb’s younger brother, did the LORD raise up for Israel?","bible_ref":"Judges 3:9","verse_text":"And when the children of Israel cried unto the LORD, the LORD raised up a deliverer to the children of Israel, who delivered them, even Othniel the son of Kenaz, Caleb’s younger brother."},"es":{"prompt":"¿Qué salvador, hermano menor de Caleb, suscitó Jehová a Israel?","bible_ref":"Jueces 3:9","verse_text":"Y clamaron los hijos de Israel á Jehová; y Jehová suscitó salvador á los hijos de Israel y librólos; es á saber, á Othoniel hijo de Cenez, hermano menor de Caleb."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Otniel"},"fr":{"text":"Othniel"},"en":{"text":"Othniel"},"es":{"text":"Othoniel"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Eúde"},"fr":{"text":"Éhud"},"en":{"text":"Ehud"},"es":{"text":"Aod"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sangar"},"fr":{"text":"Schamgar"},"en":{"text":"Shamgar"},"es":{"text":"Samgar"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-008","type":"choice","level":"hard","testament":"ot","book":"JDG","chapter":3,"verse_start":31,"verse_end":31,"texts":{"pt":{"prompt":"Com que feriu Sangar seiscentos filisteus?","bible_ref":"Juízes 3:31","verse_text":"Depois deste foi Sangar filho de Anate, o qual feriu seiscentos homens dos filisteus com uma aguilhada de bois; e ele também salvou a Israel."},"fr":{"prompt":"Avec quoi Schamgar battit-il six cents Philistins ?","bible_ref":"Juges 3:31","verse_text":"Après lui, il y eut Schamgar, fils d’Anath. Il battit six cents hommes des Philistins avec un aiguillon à bœufs. Et lui aussi fut un libérateur d’Israël."},"en":{"prompt":"With what did Shamgar slay six hundred Philistines?","bible_ref":"Judges 3:31","verse_text":"And after him was Shamgar the son of Anath, which slew of the Philistines six hundred men with an ox goad: and he also delivered Israel."},"es":{"prompt":"¿Con qué hirió Samgar a seiscientos filisteos?","bible_ref":"Jueces 3:31","verse_text":"Después de éste fué Samgar hijo de Anat, el cual hirió seiscientos hombres de los Filisteos con una aguijada de bueyes; y él también salvó á Israel."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Com uma aguilhada de bois"},"fr":{"text":"Avec un aiguillon à bœufs"},"en":{"text":"With an ox goad"},"es":{"text":"Con una aguijada de bueyes"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Com uma queixada de asno"},"fr":{"text":"Avec une mâchoire d’âne"},"en":{"text":"With a jawbone of an ass"},"es":{"text":"Con una quijada de asno"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Com uma funda"},"fr":{"text":"Avec une fronde"},"en":{"text":"With a sling"},"es":{"text":"Con una honda"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-009","type":"choice","level":"hard","testament":"ot","book":"JDG","chapter":9,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"Na parábola de Jotão, a que planta disseram por fim todas as árvores: «Vem tu, reina sobre nós»?","bible_ref":"Juízes 9:14","verse_text":"Disseram então todas as árvores ao espinheiro: Vem tu, reina sobre nós."},"fr":{"prompt":"Dans la parabole de Jotham, à quelle plante tous les arbres dirent-ils enfin : « Viens, toi, règne sur nous » ?","bible_ref":"Juges 9:14","verse_text":"Alors tous les arbres dirent au buisson d’épines: Viens, toi, règne sur nous."},"en":{"prompt":"In Jotham’s parable, to which plant did all the trees finally say, “Come thou, and reign over us”?","bible_ref":"Judges 9:14","verse_text":"Then said all the trees unto the bramble, Come thou, and reign over us."},"es":{"prompt":"En la parábola de Jotham, ¿a qué planta dijeron por fin todos los árboles: «Anda tú, reina sobre nosotros»?","bible_ref":"Jueces 9:14","verse_text":"Dijeron entonces todos los árboles al escaramujo: Anda tú, reina sobre nosotros."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Ao espinheiro"},"fr":{"text":"Au buisson d’épines"},"en":{"text":"To the bramble"},"es":{"text":"Al escaramujo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Ao cedro"},"fr":{"text":"Au cèdre"},"en":{"text":"To the cedar"},"es":{"text":"Al cedro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"À palmeira"},"fr":{"text":"Au palmier"},"en":{"text":"To the palm tree"},"es":{"text":"A la palmera"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-010","type":"choice","level":"hard","testament":"ot","book":"JDG","chapter":9,"verse_start":53,"verse_end":53,"texts":{"pt":{"prompt":"O que lançou uma mulher sobre a cabeça de Abimeleque?","bible_ref":"Juízes 9:53","verse_text":"Mas uma mulher deixou cair um pedaço de uma roda de moinho sobre a cabeça de Abimeleque, e quebrou-lhe o crânio."},"fr":{"prompt":"Que lança une femme sur la tête d’Abimélec ?","bible_ref":"Juges 9:53","verse_text":"Alors une femme lança sur la tête d’Abimélec un morceau de meule de moulin, et lui brisa le crâne."},"en":{"prompt":"What did a certain woman cast upon Abimelech’s head?","bible_ref":"Judges 9:53","verse_text":"And a certain woman cast a piece of a millstone upon Abimelech’s head, and all to brake his skull."},"es":{"prompt":"¿Qué dejó caer una mujer sobre la cabeza de Abimelech?","bible_ref":"Jueces 9:53","verse_text":"Mas una mujer dejó caer un pedazo de una rueda de molino sobre la cabeza de Abimelech, y quebróle los cascos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um pedaço de uma mó de moinho"},"fr":{"text":"Un morceau de meule de moulin"},"en":{"text":"A piece of a millstone"},"es":{"text":"Un pedazo de una rueda de molino"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma panela de água a ferver"},"fr":{"text":"Une marmite d’eau bouillante"},"en":{"text":"A pot of boiling water"},"es":{"text":"Una olla de agua hirviendo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma estaca da tenda"},"fr":{"text":"Un pieu de tente"},"en":{"text":"A nail of the tent"},"es":{"text":"Una estaca de la tienda"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-011","type":"choice","level":"hard","testament":"ot","book":"JDG","chapter":13,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Como se chamava o pai de Sansão, um homem de Zorá?","bible_ref":"Juízes 13:2","verse_text":"E havia um homem de Zorá, da tribo de Dã, o qual se chamava Manoá; e sua mulher era estéril, que nunca havia dado à luz."},"fr":{"prompt":"Comment s’appelait le père de Samson, un homme de Tsorea ?","bible_ref":"Juges 13:2","verse_text":"Il y avait un homme de Tsorea, de la famille des Danites, et qui s’appelait Manoach. Sa femme était stérile, et n’enfantait pas."},"en":{"prompt":"What was the name of Samson’s father, a man of Zorah?","bible_ref":"Judges 13:2","verse_text":"And there was a certain man of Zorah, of the family of the Danites, whose name was Manoah; and his wife was barren, and bare not."},"es":{"prompt":"¿Cómo se llamaba el padre de Samsón, un hombre de Sora?","bible_ref":"Jueces 13:2","verse_text":"Y había un hombre de Sora, de la tribu de Dan, el cual se llamaba Manoa; y su mujer era estéril, que nunca había parido."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Manoá"},"fr":{"text":"Manoach"},"en":{"text":"Manoah"},"es":{"text":"Manoa"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Elcana"},"fr":{"text":"Elkana"},"en":{"text":"Elkanah"},"es":{"text":"Elcana"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Elimeleque"},"fr":{"text":"Élimélec"},"en":{"text":"Elimelech"},"es":{"text":"Elimelech"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-012","type":"order","level":"hard","testament":"ot","book":"JDG","chapter":6,"verse_start":32,"verse_end":32,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"Juízes 6:32","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"Juges 6:32","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"Judges 6:32","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"Jueces 6:32","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Gideão recebe o nome de Jerubaal","ref":"Juízes 6:32"},"fr":{"text":"Gédéon reçoit le nom de Jerubbaal","ref":"Juges 6:32"},"en":{"text":"Gideon is called Jerubbaal","ref":"Judges 6:32"},"es":{"text":"Gedeón es llamado Jerobaal","ref":"Jueces 6:32"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Gideão recusa reinar sobre Israel","ref":"Juízes 8:23"},"fr":{"text":"Gédéon refuse de dominer sur Israël","ref":"Juges 8:23"},"en":{"text":"Gideon refuses to rule over Israel","ref":"Judges 8:23"},"es":{"text":"Gedeón rehúsa ser señor sobre Israel","ref":"Jueces 8:23"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Abimeleque mata setenta irmãos numa pedra","ref":"Juízes 9:5"},"fr":{"text":"Abimélec tue soixante-dix frères sur une pierre","ref":"Juges 9:5"},"en":{"text":"Abimelech slays seventy brothers on one stone","ref":"Judges 9:5"},"es":{"text":"Abimelech mata a setenta hermanos sobre una piedra","ref":"Jueces 9:5"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Nasce Sansão, filho de Manoá","ref":"Juízes 13:24"},"fr":{"text":"Naissance de Samson, fils de Manoach","ref":"Juges 13:24"},"en":{"text":"Samson, son of Manoah, is born","ref":"Judges 13:24"},"es":{"text":"Nace Samsón, hijo de Manoa","ref":"Jueces 13:24"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-013","type":"verse","level":"hard","testament":"ot","book":"JDG","chapter":5,"verse_start":31,"verse_end":31,"texts":{"pt":{"prompt":"Assim pereçam todos os teus inimigos, ó SENHOR: Mas os que lhe amam, sejam como o _____ quando nasce em sua força. E a terra repousou quarenta anos.","bible_ref":"Juízes 5:31","verse_text":"Assim pereçam todos os teus inimigos, ó SENHOR: Mas os que lhe amam, sejam como o sol quando nasce em sua força. E a terra repousou quarenta anos."},"fr":{"prompt":"Périssent ainsi tous tes ennemis, ô Éternel! Ceux qui l’aiment sont comme le _____, Quand il paraît dans sa force. Le pays fut en repos pendant quarante ans.","bible_ref":"Juges 5:31","verse_text":"Périssent ainsi tous tes ennemis, ô Éternel! Ceux qui l’aiment sont comme le soleil, Quand il paraît dans sa force. Le pays fut en repos pendant quarante ans."},"en":{"prompt":"So let all thine enemies perish, O LORD: but let them that love him be as the _____ when he goeth forth in his might. And the land had rest forty years.","bible_ref":"Judges 5:31","verse_text":"So let all thine enemies perish, O LORD: but let them that love him be as the sun when he goeth forth in his might. And the land had rest forty years."},"es":{"prompt":"Así perezcan todos tus enemigos, oh Jehová: mas los que le aman, sean como el _____ cuando nace en su fuerza. Y la tierra reposó cuarenta años.","bible_ref":"Jueces 5:31","verse_text":"Así perezcan todos tus enemigos, oh Jehová: mas los que le aman, sean como el sol cuando nace en su fuerza. Y la tierra reposó cuarenta años."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"trovão"},"fr":{"text":"tonnerre"},"en":{"text":"thunder"},"es":{"text":"trueno"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"vento"},"fr":{"text":"vent"},"en":{"text":"wind"},"es":{"text":"viento"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"rio"},"fr":{"text":"fleuve"},"en":{"text":"river"},"es":{"text":"río"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"sol"},"fr":{"text":"soleil"},"en":{"text":"sun"},"es":{"text":"sol"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-014","type":"verse","level":"hard","testament":"ot","book":"JDG","chapter":6,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"E o anjo do SENHOR se lhe apareceu, e disse-lhe: O SENHOR é contigo, homem _____.","bible_ref":"Juízes 6:12","verse_text":"E o anjo do SENHOR se lhe apareceu, e disse-lhe: O SENHOR é contigo, homem esforçado."},"fr":{"prompt":"L’ange de l’Éternel lui apparut, et lui dit: L’Éternel est avec toi, _____ héros!","bible_ref":"Juges 6:12","verse_text":"L’ange de l’Éternel lui apparut, et lui dit: L’Éternel est avec toi, vaillant héros!"},"en":{"prompt":"And the angel of the LORD appeared unto him, and said unto him, The LORD is with thee, thou mighty man of _____.","bible_ref":"Judges 6:12","verse_text":"And the angel of the LORD appeared unto him, and said unto him, The LORD is with thee, thou mighty man of valour."},"es":{"prompt":"Y el ángel de Jehová se le apareció, y díjole: Jehová es contigo, varón _____.","bible_ref":"Jueces 6:12","verse_text":"Y el ángel de Jehová se le apareció, y díjole: Jehová es contigo, varón esforzado."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"fiel"},"fr":{"text":"fidèle"},"en":{"text":"faith"},"es":{"text":"fiel"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"sábio"},"fr":{"text":"sage"},"en":{"text":"wisdom"},"es":{"text":"sabio"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"justo"},"fr":{"text":"juste"},"en":{"text":"justice"},"es":{"text":"justo"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"esforçado"},"fr":{"text":"vaillant"},"en":{"text":"valour"},"es":{"text":"esforzado"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-015","type":"choice","level":"hard","testament":"ot","book":"RUT","chapter":4,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Segundo Rute 4:7, o que tirava um homem e dava ao outro para confirmar um resgate em Israel?","bible_ref":"Rute 4:7","verse_text":"Havia já de longo tempo este costume em Israel na remissão ou contrato, que para a confirmação de qualquer negócio, o um se tirava o sapato e o dava a seu companheiro: e este era o testemunho em Israel."},"fr":{"prompt":"Selon Ruth 4:7, qu’ôtait un homme et donnait-il à l’autre pour valider un rachat en Israël ?","bible_ref":"Ruth 4:7","verse_text":"Autrefois en Israël, pour valider une affaire quelconque relative à un rachat ou à un échange, l’un ôtait son soulier et le donnait à l’autre: cela servait de témoignage en Israël."},"en":{"prompt":"According to Ruth 4:7, what did a man pluck off and give to his neighbour to confirm a redemption in Israel?","bible_ref":"Ruth 4:7","verse_text":"Now this was the manner in former time in Israel concerning redeeming and concerning changing, for to confirm all things; a man plucked off his shoe, and gave it to his neighbour: and this was a testimony in Israel."},"es":{"prompt":"Según Ruth 4:7, ¿qué se quitaba un hombre y daba a su compañero para confirmar una redención en Israel?","bible_ref":"Rut 4:7","verse_text":"Había ya de largo tiempo esta costumbre en Israel en la redención ó contrato, que para la confirmación de cualquier negocio, el uno se quitaba el zapato y lo daba á su compañero: y este era el testimonio en Israel."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O sapato"},"fr":{"text":"Son soulier"},"en":{"text":"His shoe"},"es":{"text":"El zapato"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O anel"},"fr":{"text":"Son anneau"},"en":{"text":"His ring"},"es":{"text":"El anillo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A capa"},"fr":{"text":"Son manteau"},"en":{"text":"His cloak"},"es":{"text":"La capa"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-016","type":"choice","level":"hard","testament":"ot","book":"RUT","chapter":4,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Quem deu o nome de Obede ao filho de Rute?","bible_ref":"Rute 4:17","verse_text":"E as vizinhas dizendo, a Noemi nasceu um filho, lhe puseram nome; e chamaram-lhe Obede. Este é pai de Jessé, pai de Davi."},"fr":{"prompt":"Qui donna le nom d’Obed au fils de Ruth ?","bible_ref":"Ruth 4:17","verse_text":"Les voisines lui donnèrent un nom, en disant: Un fils est né à Naomi! Et elles l’appelèrent Obed. Ce fut le père d’Isaï père de David."},"en":{"prompt":"Who gave Ruth’s son the name Obed?","bible_ref":"Ruth 4:17","verse_text":"And the women her neighbours gave it a name, saying, There is a son born to Naomi; and they called his name Obed: he is the father of Jesse, the father of David."},"es":{"prompt":"¿Quién puso el nombre de Obed al hijo de Ruth?","bible_ref":"Rut 4:17","verse_text":"Y las vecinas diciendo, A Noemi ha nacido un hijo, le pusieron nombre; y llamáronle Obed. Este es padre de Isaí, padre de David."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"As vizinhas de Noemi"},"fr":{"text":"Les voisines de Naomi"},"en":{"text":"The women, Naomi’s neighbours"},"es":{"text":"Las vecinas de Noemi"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Boaz"},"fr":{"text":"Boaz"},"en":{"text":"Boaz"},"es":{"text":"Booz"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Os anciãos da cidade"},"fr":{"text":"Les anciens de la ville"},"en":{"text":"The elders of the city"},"es":{"text":"Los ancianos de la ciudad"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-017","type":"order","level":"hard","testament":"ot","book":"RUT","chapter":2,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"Ordena estes episódios pela ordem em que aconteceram.","bible_ref":"Rute 2:14","verse_text":null},"fr":{"prompt":"Mets ces épisodes dans l’ordre où ils se sont produits.","bible_ref":"Ruth 2:14","verse_text":null},"en":{"prompt":"Put these episodes in the order they happened.","bible_ref":"Ruth 2:14","verse_text":null},"es":{"prompt":"Ordena estos episodios según ocurrieron.","bible_ref":"Rut 2:14","verse_text":null}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"Boaz convida Rute a comer com os ceifeiros","ref":"Rute 2:14"},"fr":{"text":"Boaz invite Ruth à manger avec les moissonneurs","ref":"Ruth 2:14"},"en":{"text":"Boaz invites Ruth to eat with the reapers","ref":"Ruth 2:14"},"es":{"text":"Booz invita a Ruth a comer con los segadores","ref":"Rut 2:14"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Rute debulha cerca de um efa de cevada","ref":"Rute 2:17"},"fr":{"text":"Ruth bat environ un épha d’orge","ref":"Ruth 2:17"},"en":{"text":"Ruth beats out about an ephah of barley","ref":"Ruth 2:17"},"es":{"text":"Ruth desgrana como un epha de cebada","ref":"Rut 2:17"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Boaz mede seis medidas de cevada para Rute","ref":"Rute 3:15"},"fr":{"text":"Boaz mesure six mesures d’orge pour Ruth","ref":"Ruth 3:15"},"en":{"text":"Boaz measures six measures of barley for Ruth","ref":"Ruth 3:15"},"es":{"text":"Booz mide seis medidas de cebada para Ruth","ref":"Rut 3:15"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Boaz chama dez anciãos da cidade","ref":"Rute 4:2"},"fr":{"text":"Boaz prend dix anciens de la ville","ref":"Ruth 4:2"},"en":{"text":"Boaz takes ten elders of the city","ref":"Ruth 4:2"},"es":{"text":"Booz toma diez ancianos de la ciudad","ref":"Rut 4:2"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-018","type":"choice","level":"hard","testament":"ot","book":"1SA","chapter":17,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Qual era a altura de Golias, de Gate?","bible_ref":"1 Samuel 17:4","verse_text":"Saiu então um homem do acampamento dos filisteus que se pôs entre os dois campos, o qual se chamava Golias, de Gate, e tinha de altura seis côvados e um palmo."},"fr":{"prompt":"Quelle était la taille de Goliath, de Gath ?","bible_ref":"1 Samuel 17:4","verse_text":"Un homme sortit alors du camp des Philistins et s’avança entre les deux armées. Il se nommait Goliath, il était de Gath, et il avait une taille de six coudées et un empan."},"en":{"prompt":"What was the height of Goliath of Gath?","bible_ref":"1 Samuel 17:4","verse_text":"And there went out a champion out of the camp of the Philistines, named Goliath, of Gath, whose height was six cubits and a span."},"es":{"prompt":"¿Cuál era la altura de Goliath, de Gath?","bible_ref":"1 Samuel 17:4","verse_text":"Salió entonces un varón del campo de los Filisteos que se puso entre los dos campos, el cual se llamaba Goliath, de Gath, y tenía de altura seis codos y un palmo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Seis côvados e um palmo"},"fr":{"text":"Six coudées et un empan"},"en":{"text":"Six cubits and a span"},"es":{"text":"Seis codos y un palmo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Oito côvados"},"fr":{"text":"Huit coudées"},"en":{"text":"Eight cubits"},"es":{"text":"Ocho codos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dez côvados e um palmo"},"fr":{"text":"Dix coudées et un empan"},"en":{"text":"Ten cubits and a span"},"es":{"text":"Diez codos y un palmo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-019","type":"choice","level":"hard","testament":"ot","book":"1SA","chapter":17,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Quantos filhos tinha Jessé, o pai de David?","bible_ref":"1 Samuel 17:12","verse_text":"E Davi era filho daquele homem efrateu de Belém de Judá, cujo nome era Jessé, o qual tinha oito filhos; e era este homem no tempo de Saul, velho, e de grande idade entre os homens."},"fr":{"prompt":"Combien de fils avait Isaï, le père de David ?","bible_ref":"1 Samuel 17:12","verse_text":"Or David était fils de cet Éphratien de Bethléhem de Juda, nommé Isaï, qui avait huit fils, et qui, du temps de Saül, était vieux, avancé en âge."},"en":{"prompt":"How many sons did Jesse, David’s father, have?","bible_ref":"1 Samuel 17:12","verse_text":"Now David was the son of that Ephrathite of Beth-lehem-judah, whose name was Jesse; and he had eight sons: and the man went among men for an old man in the days of Saul."},"es":{"prompt":"¿Cuántos hijos tenía Isaí, el padre de David?","bible_ref":"1 Samuel 17:12","verse_text":"Y David era hijo de aquel hombre Ephrateo de Beth-lehem de Judá, cuyo nombre era Isaí, el cual tenía ocho hijos; y era este hombre en el tiempo de Saúl, viejo, y de grande edad entre los hombres."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Oito"},"fr":{"text":"Huit"},"en":{"text":"Eight"},"es":{"text":"Ocho"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Seis"},"fr":{"text":"Six"},"en":{"text":"Six"},"es":{"text":"Seis"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dez"},"fr":{"text":"Dix"},"en":{"text":"Ten"},"es":{"text":"Diez"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-020","type":"choice","level":"hard","testament":"ot","book":"1SA","chapter":21,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Que espada deu o sacerdote a David?","bible_ref":"1 Samuel 21:9","verse_text":"E o sacerdote respondeu: A espada de Golias o filisteu, que tu venceste no vale de Elá, está aqui embrulhada em um véu detrás do éfode: se tu queres tomá-la, toma-a: porque aqui não há outra a não ser essa. E disse Davi: Nenhuma como ela: dá-a a mim."},"fr":{"prompt":"Quelle épée le sacrificateur donna-t-il à David ?","bible_ref":"1 Samuel 21:9","verse_text":"Le sacrificateur répondit: Voici l’épée de Goliath, le Philistin, que tu as tué dans la vallée des térébinthes; elle est enveloppée dans un drap, derrière l’éphod; si tu veux la prendre, prends-la, car il n’y en a pas d’autre ici. Et David dit: Il n’y en a point de pareille; donne-la-moi."},"en":{"prompt":"Which sword did the priest give to David?","bible_ref":"1 Samuel 21:9","verse_text":"And the priest said, The sword of Goliath the Philistine, whom thou slewest in the valley of Elah, behold, it is here wrapped in a cloth behind the ephod: if thou wilt take that, take it: for there is no other save that here. And David said, There is none like that; give it me."},"es":{"prompt":"¿Qué espada dio el sacerdote a David?","bible_ref":"1 Samuel 21:9","verse_text":"Y el sacerdote respondió: La espada de Goliath el Filisteo, que tú venciste en el valle del Alcornoque, está aquí envuelta en un velo detrás del ephod: si tú quieres tomarla, tómala: porque aquí no hay otra sino esa. Y dijo David: Ninguna como ella: dámela."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A espada de Golias"},"fr":{"text":"L’épée de Goliath"},"en":{"text":"The sword of Goliath"},"es":{"text":"La espada de Goliath"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A espada de Saul"},"fr":{"text":"L’épée de Saül"},"en":{"text":"The sword of Saul"},"es":{"text":"La espada de Saúl"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A espada de Abner"},"fr":{"text":"L’épée d’Abner"},"en":{"text":"The sword of Abner"},"es":{"text":"La espada de Abner"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-021","type":"choice","level":"hard","testament":"ot","book":"1SA","chapter":4,"verse_start":18,"verse_end":18,"texts":{"pt":{"prompt":"Como morreu o sacerdote Eli quando ouviu falar da arca de Deus?","bible_ref":"1 Samuel 4:18","verse_text":"E aconteceu que quando ele fez menção da arca de Deus, Eli caiu até atrás da cadeira ao lado da porta, e o seu pescoço se quebrou, e ele morreu: porque era homem velho e pesado. E havia julgado a Israel quarenta anos."},"fr":{"prompt":"Comment mourut le sacrificateur Éli quand il entendit parler de l’arche de Dieu ?","bible_ref":"1 Samuel 4:18","verse_text":"A peine eut-il fait mention de l’arche de Dieu, qu’Éli tomba de son siège à la renverse, à côté de la porte; il se rompit la nuque et mourut, car c’était un homme vieux et pesant. Il avait été juge en Israël pendant quarante ans."},"en":{"prompt":"How did Eli the priest die when he heard mention of the ark of God?","bible_ref":"1 Samuel 4:18","verse_text":"And it came to pass, when he made mention of the ark of God, that he fell from off the seat backward by the side of the gate, and his neck brake, and he died: for he was an old man, and heavy. And he had judged Israel forty years."},"es":{"prompt":"¿Cómo murió el sacerdote Eli cuando oyó hablar del arca de Dios?","bible_ref":"1 Samuel 4:18","verse_text":"Y aconteció que como él hizo mención del arca de Dios, Eli cayó hacia atrás de la silla al lado de la puerta, y quebrósele la cerviz, y murió: porque era hombre viejo y pesado. Y había juzgado á Israel cuarenta años."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Caiu da cadeira para trás e partiu o pescoço"},"fr":{"text":"Il tomba de son siège à la renverse et se rompit la nuque"},"en":{"text":"He fell backward from his seat and his neck brake"},"es":{"text":"Cayó hacia atrás de la silla y se quebró la cerviz"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Morreu na batalha contra os filisteus"},"fr":{"text":"Il mourut dans la bataille contre les Philistins"},"en":{"text":"He died in the battle against the Philistines"},"es":{"text":"Murió en la batalla contra los filisteos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Morreu de velhice na sua cama"},"fr":{"text":"Il mourut de vieillesse dans son lit"},"en":{"text":"He died of old age in his bed"},"es":{"text":"Murió de vejez en su cama"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-022","type":"choice","level":"hard","testament":"ot","book":"1SA","chapter":14,"verse_start":27,"verse_end":27,"texts":{"pt":{"prompt":"O que provou Jónatas sem saber do juramento do seu pai?","bible_ref":"1 Samuel 14:27","verse_text":"Porém Jônatas não havia ouvido quando seu pai conjurou ao povo, e estendeu a ponta de uma vara que trazia em sua mão, e molhou-a em um favo de mel, e chegou sua mão a sua boca; e seus olhos se iluminaram."},"fr":{"prompt":"Que goûta Jonathan sans connaître le serment de son père ?","bible_ref":"1 Samuel 14:27","verse_text":"Jonathan ignorait le serment que son père avait fait faire au peuple; il avança le bout du bâton qu’il avait à la main, le plongea dans un rayon de miel, et ramena la main à la bouche; et ses yeux furent éclaircis."},"en":{"prompt":"What did Jonathan taste, not knowing his father’s oath?","bible_ref":"1 Samuel 14:27","verse_text":"But Jonathan heard not when his father charged the people with the oath: wherefore he put forth the end of the rod that was in his hand, and dipped it in an honeycomb, and put his hand to his mouth; and his eyes were enlightened."},"es":{"prompt":"¿Qué probó Jonathán sin saber del juramento de su padre?","bible_ref":"1 Samuel 14:27","verse_text":"Empero Jonathán no había oído cuando su padre conjuró al pueblo, y alargó la punta de una vara que traía en su mano, y mojóla en un panal de miel, y llegó su mano á su boca; y sus ojos fueron aclarados."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Mel"},"fr":{"text":"Du miel"},"en":{"text":"Honey"},"es":{"text":"Miel"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Vinho"},"fr":{"text":"Du vin"},"en":{"text":"Wine"},"es":{"text":"Vino"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Figos"},"fr":{"text":"Des figues"},"en":{"text":"Figs"},"es":{"text":"Higos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-023","type":"choice","level":"hard","testament":"ot","book":"1SA","chapter":30,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"A que cidade chegaram David e os seus homens ao terceiro dia, encontrando-a queimada pelos amalequitas?","bible_ref":"1 Samuel 30:1","verse_text":"E Quando Davi e os seus vieram a Ziclague o terceiro dia, os de Amaleque haviam invadido o sul e a Ziclague, e haviam assolado a Ziclague, e posto-a a fogo."},"fr":{"prompt":"Dans quelle ville David et ses gens arrivèrent-ils le troisième jour, la trouvant brûlée par les Amalécites ?","bible_ref":"1 Samuel 30:1","verse_text":"Lorsque David arriva le troisième jour à Tsiklag avec ses gens, les Amalécites avaient fait une invasion dans le midi et à Tsiklag. Ils avaient détruit et brûlé Tsiklag,"},"en":{"prompt":"To which city did David and his men come on the third day, finding it burned by the Amalekites?","bible_ref":"1 Samuel 30:1","verse_text":"And it came to pass, when David and his men were come to Ziklag on the third day, that the Amalekites had invaded the south, and Ziklag, and smitten Ziklag, and burned it with fire;"},"es":{"prompt":"¿A qué ciudad llegaron David y los suyos al tercer día, hallándola quemada por los amalecitas?","bible_ref":"1 Samuel 30:1","verse_text":"Y cuando David y los suyos vinieron á Siclag al tercer día, los de Amalec habían invadido el mediodía y á Siclag, y habían desolado á Siclag, y puéstola á fuego."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Ziclague"},"fr":{"text":"Tsiklag"},"en":{"text":"Ziklag"},"es":{"text":"Siclag"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Gate"},"fr":{"text":"Gath"},"en":{"text":"Gath"},"es":{"text":"Gath"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Hebrom"},"fr":{"text":"Hébron"},"en":{"text":"Hebron"},"es":{"text":"Hebrón"}}}]}$json$::jsonb);
