select public.upsert_bank_question($json${"id":"hist2-hard-026","type":"verse","level":"hard","testament":"ot","book":"1SA","chapter":26,"verse_start":23,"verse_end":23,"texts":{"pt":{"prompt":"E o SENHOR pague a cada um sua justiça e sua lealdade: que o SENHOR havia te entregue hoje em minha mão, mas eu não quis estender minha mão sobre o _____ do SENHOR.","bible_ref":"1 Samuel 26:23","verse_text":"E o SENHOR pague a cada um sua justiça e sua lealdade: que o SENHOR havia te entregue hoje em minha mão, mas eu não quis estender minha mão sobre o ungido do SENHOR."},"fr":{"prompt":"L’Éternel rendra à chacun selon sa justice et sa fidélité; car l’Éternel t’avait livré aujourd’hui entre mes mains, et je n’ai pas voulu porter la main sur l’_____ de l’Éternel.","bible_ref":"1 Samuel 26:23","verse_text":"L’Éternel rendra à chacun selon sa justice et sa fidélité; car l’Éternel t’avait livré aujourd’hui entre mes mains, et je n’ai pas voulu porter la main sur l’oint de l’Éternel."},"en":{"prompt":"The LORD render to every man his righteousness and his faithfulness: for the LORD delivered thee into my hand to day, but I would not stretch forth mine hand against the LORD’s _____.","bible_ref":"1 Samuel 26:23","verse_text":"The LORD render to every man his righteousness and his faithfulness: for the LORD delivered thee into my hand to day, but I would not stretch forth mine hand against the LORD’s anointed."},"es":{"prompt":"Y Jehová pague á cada uno su justicia y su lealtad: que Jehová te había entregado hoy en mi mano, mas yo no quise extender mi mano sobre el _____ de Jehová.","bible_ref":"1 Samuel 26:23","verse_text":"Y Jehová pague á cada uno su justicia y su lealtad: que Jehová te había entregado hoy en mi mano, mas yo no quise extender mi mano sobre el ungido de Jehová."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"amigo"},"fr":{"text":"ami"},"en":{"text":"friend"},"es":{"text":"amigo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"estrangeiro"},"fr":{"text":"étranger"},"en":{"text":"stranger"},"es":{"text":"extranjero"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"inimigo"},"fr":{"text":"ennemi"},"en":{"text":"enemy"},"es":{"text":"enemigo"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"ungido"},"fr":{"text":"oint"},"en":{"text":"anointed"},"es":{"text":"ungido"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-027","type":"choice","level":"hard","testament":"ot","book":"2SA","chapter":14,"verse_start":26,"verse_end":26,"texts":{"pt":{"prompt":"Quanto pesava o cabelo de Absalão quando o cortava ao fim do ano?","bible_ref":"2 Samuel 14:26","verse_text":"E quando se cortava o cabelo, (o qual fazia ao fim de cada ano, pois lhe incomodava, e por isso se o cortava,) pesava o cabelo de sua cabeça duzentos siclos de peso real."},"fr":{"prompt":"Combien pesait la chevelure d’Absalom quand il la rasait chaque année ?","bible_ref":"2 Samuel 14:26","verse_text":"Lorsqu’il se rasait la tête, c’était chaque année qu’il se la rasait, parce que sa chevelure lui pesait, le poids des cheveux de sa tête était de deux cents sicles, poids du roi."},"en":{"prompt":"How much did the hair of Absalom’s head weigh when he polled it each year?","bible_ref":"2 Samuel 14:26","verse_text":"And when he polled his head, (for it was at every year’s end that he polled it: because the hair was heavy on him, therefore he polled it:) he weighed the hair of his head at two hundred shekels after the king’s weight."},"es":{"prompt":"¿Cuánto pesaba el cabello de Absalom cuando se lo cortaba cada año?","bible_ref":"2 Samuel 14:26","verse_text":"Y cuando se cortaba el cabello, (lo cual hacía al fin de cada año, pues le causaba molestia, y por eso se lo cortaba), pesaba el cabello de su cabeza doscientos siclos de peso real."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Duzentos siclos"},"fr":{"text":"Deux cents sicles"},"en":{"text":"Two hundred shekels"},"es":{"text":"Doscientos siclos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Cinquenta siclos"},"fr":{"text":"Cinquante sicles"},"en":{"text":"Fifty shekels"},"es":{"text":"Cincuenta siclos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Mil siclos"},"fr":{"text":"Mille sicles"},"en":{"text":"A thousand shekels"},"es":{"text":"Mil siclos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-028","type":"choice","level":"hard","testament":"ot","book":"2SA","chapter":3,"verse_start":27,"verse_end":27,"texts":{"pt":{"prompt":"Quem matou Abner à porta de Hebrom, por causa da morte de Asael?","bible_ref":"2 Samuel 3:27","verse_text":"E quando Abner voltou a Hebrom, apartou-o Joabe ao meio da porta, falando com ele brandamente, e ali lhe feriu pela quinta costela, por causa da morte de Asael seu irmão, e morreu."},"fr":{"prompt":"Qui tua Abner à la porte d’Hébron, pour venger la mort d’Asaël ?","bible_ref":"2 Samuel 3:27","verse_text":"Lorsque Abner fut de retour à Hébron, Joab le tira à l’écart au milieu de la porte, comme pour lui parler en secret, et là il le frappa au ventre et le tua, pour venger la mort d’Asaël, son frère."},"en":{"prompt":"Who smote Abner in the gate of Hebron for the blood of Asahel?","bible_ref":"2 Samuel 3:27","verse_text":"And when Abner was returned to Hebron, Joab took him aside in the gate to speak with him quietly, and smote him there under the fifth rib, that he died, for the blood of Asahel his brother."},"es":{"prompt":"¿Quién hirió a Abner en la puerta de Hebrón, a causa de la muerte de Asael?","bible_ref":"2 Samuel 3:27","verse_text":"Y como Abner volvió á Hebrón, apartólo Joab al medio de la puerta, hablando con él blandamente, y allí le hirió por la quinta costilla, á causa de la muerte de Asael su hermano, y murió."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Joabe"},"fr":{"text":"Joab"},"en":{"text":"Joab"},"es":{"text":"Joab"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Benaia"},"fr":{"text":"Benaja"},"en":{"text":"Benaiah"},"es":{"text":"Benahía"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Itai"},"fr":{"text":"Ittaï"},"en":{"text":"Ittai"},"es":{"text":"Ittai"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-029","type":"choice","level":"hard","testament":"ot","book":"2SA","chapter":19,"verse_start":32,"verse_end":32,"texts":{"pt":{"prompt":"Que idade tinha Barzilai, que sustentou o rei David em Maanaim?","bible_ref":"2 Samuel 19:32","verse_text":"E era Barzilai muito velho, de oitenta anos, o qual havia dado provisão ao rei quando estava em Maanaim, porque era homem muito rico."},"fr":{"prompt":"Quel âge avait Barzillaï, qui avait entretenu le roi David à Mahanaïm ?","bible_ref":"2 Samuel 19:32","verse_text":"Barzillaï était très vieux, âgé de quatre-vingts ans. Il avait entretenu le roi pendant son séjour à Mahanaïm, car c’était un homme fort riche."},"en":{"prompt":"How old was Barzillai, who provided the king of sustenance at Mahanaim?","bible_ref":"2 Samuel 19:32","verse_text":"Now Barzillai was a very aged man, even fourscore years old: and he had provided the king of sustenance while he lay at Mahanaim; for he was a very great man."},"es":{"prompt":"¿Qué edad tenía Barzillai, que dio provisión al rey David en Mahanaim?","bible_ref":"2 Samuel 19:32","verse_text":"Y era Barzillai muy viejo, de ochenta años, el cual había dado provisión al rey cuando estaba en Mahanaim, porque era hombre muy rico."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Oitenta anos"},"fr":{"text":"Quatre-vingts ans"},"en":{"text":"Fourscore years"},"es":{"text":"Ochenta años"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Setenta anos"},"fr":{"text":"Soixante-dix ans"},"en":{"text":"Threescore and ten years"},"es":{"text":"Setenta años"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Cem anos"},"fr":{"text":"Cent ans"},"en":{"text":"An hundred years"},"es":{"text":"Cien años"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"hist2-hard-030","type":"choice","level":"hard","testament":"ot","book":"2SA","chapter":4,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Que idade tinha Mefibosete quando caiu e ficou coxo?","bible_ref":"2 Samuel 4:4","verse_text":"E Jônatas, filho de Saul, tinha um filho aleijado dos pés de idade de cinco anos, o qual, quando a notícia da morte de Saul e de Jônatas veio de Jezreel, a sua ama o tomou e fugiu; e quando ela ia fugindo depressa, o menino caiu e ficou aleijado. Seu nome era Mefibosete."},"fr":{"prompt":"Quel âge avait Mephiboscheth quand il tomba et resta boiteux ?","bible_ref":"2 Samuel 4:4","verse_text":"Jonathan, fils de Saül, avait un fils perclus des pieds; et âgé de cinq ans lorsqu’arriva de Jizreel la nouvelle de la mort de Saül et de Jonathan; sa nourrice le prit et s’enfuit, et, comme elle précipitait sa fuite, il tomba et resta boiteux; son nom était Mephiboscheth."},"en":{"prompt":"How old was Mephibosheth when he fell and became lame?","bible_ref":"2 Samuel 4:4","verse_text":"And Jonathan, Saul’s son, had a son that was lame of his feet. He was five years old when the tidings came of Saul and Jonathan out of Jezreel, and his nurse took him up, and fled: and it came to pass, as she made haste to flee, that he fell, and became lame. And his name was Mephibosheth."},"es":{"prompt":"¿Qué edad tenía Mephi-boseth cuando cayó y quedó cojo?","bible_ref":"2 Samuel 4:4","verse_text":"Y Jonathán, hijo de Saúl, tenía un hijo lisiado de los pies de edad de cinco años: que cuando la noticia de la muerte de Saúl y de Jonathán vino de Jezreel, tomóle su ama y huyó; y como iba huyendo con celeridad, cayó el niño y quedó cojo. Su nombre era Mephi-boseth."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Cinco anos"},"fr":{"text":"Cinq ans"},"en":{"text":"Five years"},"es":{"text":"Cinco años"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Dois anos"},"fr":{"text":"Deux ans"}